#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_OUT_1 2
#define GPIO_OUT_2 3
#define CONSUMER "gpio-toggle"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line1 = gpiod_chip_get_line(chip, GPIO_OUT_1);
    if (!line1) {
        perror("gpiod_chip_get_line (GPIO 2)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_OUT_2);
    if (!line2) {
        perror("gpiod_chip_get_line (GPIO 3)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initial value 0 */
    ret = gpiod_line_request_output(line1, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO 2)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line2, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO 3)");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: toggle each line once every 2 seconds */
    while (keep_running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0) {
            perror("gpiod_line_get_value (GPIO 2)");
            break;
        }
        if (val2 < 0) {
            perror("gpiod_line_get_value (GPIO 3)");
            break;
        }

        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_OUT_1, val1, GPIO_OUT_2, val2);
        fflush(stdout);

        /* Toggle both lines */
        ret = gpiod_line_set_value(line1, val1 ? 0 : 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 2)");
            break;
        }
        ret = gpiod_line_set_value(line2, val2 ? 0 : 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 3)");
            break;
        }

        /* Sleep 2 seconds, but wake early if interrupted */
        for (int i = 0; i < 20 && keep_running; i++) {
            usleep(100000); /* 100 ms */
        }
    }

    /* Clean shutdown: set both lines low and release resources */
    if (line1) {
        gpiod_line_set_value(line1, 0);
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_set_value(line2, 0);
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

