#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 2
#define CONSUMER "gpio-digital-output"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for BCM 2 */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW (0) */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d (BCM) output control started. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);
    fflush(stdout);

    while (program_running) {
        int value = (rand() % 2);

        /* Apply the value */
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("Set GPIO %d to %d\n", GPIO_LINE_OFFSET, value);
        fflush(stdout);

        /* Sleep for 5 seconds, but wake early if interrupted */
        for (int i = 0; i < POLL_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    /* Clean up: release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nGPIO released. Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_BEGIN (1 << 15)
#define ADS1115_CONFIG_MUX_AIN0_GND (0x4000)
#define ADS1115_CONFIG_PGA_4_096V (0x0200)
#define ADS1115_CONFIG_MODE_SINGLE (0x0100)
#define ADS1115_CONFIG_DR_128SPS (0x0080)
#define ADS1115_CONFIG_CQUE_NONE (0x0003)

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = {reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF)};
    if (write(fd, buf, 3) != 3) {
        perror("i2c_write_reg16: write");
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg16: write");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("i2c_read_reg16: read");
        return -1;
    }
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_read_raw(int fd, int16_t *raw) {
    uint16_t config = ADS1115_CONFIG_OS_BEGIN |
                      ADS1115_CONFIG_MUX_AIN0_GND |
                      ADS1115_CONFIG_PGA_4_096V |
                      ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS |
                      ADS1115_CONFIG_CQUE_NONE;

    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, config) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);

    uint16_t cfg;
    if (i2c_read_reg16(fd, ADS1115_REG_CONFIG, &cfg) < 0)
        return -1;

    if (!(cfg & ADS1115_CONFIG_OS_BEGIN)) {
        fprintf(stderr, "ADS1115 conversion not complete\n");
        return -1;
    }

    uint16_t conv;
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &conv) < 0)
        return -1;

    *raw = (int16_t)conv;
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        int16_t raw;
        if (ads1115_read_raw(fd, &raw) < 0) {
            fprintf(stderr, "ADC read failed\n");
            break;
        }
        printf("Raw: %d\n", raw);
        fflush(stdout);
        usleep(500000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MLX90614_ADDR 0x5A
#define MLX90614_TA 0x06
#define MLX90614_TOBJ1 0x07
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[3];
    ssize_t n = read(fd, buf, 3);
    if (n != 3) {
        return -1;
    }
    *val = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static float convert_temp(uint16_t raw) {
    return (float)raw * 0.02f - 273.15f;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                MLX90614_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t raw_ta, raw_tobj;

        if (i2c_read_word(fd, MLX90614_TA, &raw_ta) < 0) {
            fprintf(stderr, "Error reading ambient temperature: %s\n", strerror(errno));
            break;
        }
        if (i2c_read_word(fd, MLX90614_TOBJ1, &raw_tobj) < 0) {
            fprintf(stderr, "Error reading object temperature: %s\n", strerror(errno));
            break;
        }

        float ta = convert_temp(raw_ta);
        float tobj = convert_temp(raw_tobj);

        printf("Ambient Temperature: %.2f C\n", ta);
        printf("Object Temperature: %.2f C\n", tobj);
        fflush(stdout);

        if (running) {
            sleep(5);
        }
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_4  4
#define GPIO_17 17

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line4 = NULL, *line17 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line4 = gpiod_chip_get_line(chip, GPIO_4);
    if (!line4) {
        perror("gpiod_chip_get_line(4)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line(17)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initial value 1 (HIGH) */
    ret = gpiod_line_request_output(line4, "gpio-control", 1);
    if (ret < 0) {
        perror("gpiod_line_request_output(4)");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line17, "gpio-control", 1);
    if (ret < 0) {
        perror("gpiod_line_request_output(17)");
        goto cleanup;
    }

    /* Apply HIGH to both lines */
    ret = gpiod_line_set_value(line4, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value(4)");
        goto cleanup;
    }

    ret = gpiod_line_set_value(line17, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value(17)");
        goto cleanup;
    }

    printf("GPIO 4 and GPIO 17 set to HIGH\n");
    fflush(stdout);

    /* Wait for signal or 5 seconds (whichever comes first) */
    for (int i = 0; i < 50 && running; i++) {
        usleep(100000); /* 100 ms */
    }

    /* Release lines and close chip */
    gpiod_line_release(line4);
    gpiod_line_release(line17);
    gpiod_chip_close(chip);

    printf("GPIO 4 and GPIO 17 set to LOW\n");
    fflush(stdout);
    return EXIT_SUCCESS;

cleanup:
    if (line4)  gpiod_line_release(line4);
    if (line17) gpiod_line_release(line17);
    if (chip)   gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_BEGIN (1 << 15)
#define ADS1115_CONFIG_MUX_AIN0_GND (0x4000)
#define ADS1115_CONFIG_PGA_4_096V (0x0200)
#define ADS1115_CONFIG_MODE_SINGLE (0x0100)
#define ADS1115_CONFIG_DR_128SPS (0x0080)
#define ADS1115_CONFIG_CQUE_NONE (0x0003)

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int16_t convert_to_signed(uint16_t raw) {
    return (int16_t)raw;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        goto cleanup;
    }

    uint16_t config = ADS1115_CONFIG_OS_BEGIN |
                      ADS1115_CONFIG_MUX_AIN0_GND |
                      ADS1115_CONFIG_PGA_4_096V |
                      ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS |
                      ADS1115_CONFIG_CQUE_NONE;

    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, config) < 0) {
        perror("i2c_write_reg16 config");
        goto cleanup;
    }

    while (running) {
        uint16_t raw;
        if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &raw) < 0) {
            perror("i2c_read_reg16 conversion");
            goto cleanup;
        }

        int16_t value = convert_to_signed(raw);
        printf("ADC Value: %d\n", value);
        fflush(stdout);

        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) close(fd);
    return ret;
}

