#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI7021_ADDR 0x40
#define I2C_BUS "/dev/i2c-1"
#define MEASURE_TEMP_HOLD 0xE3
#define MEASURE_HUM_HOLD  0xE5
#define READ_TEMP_PREV    0xE0
#define READ_HUM_PREV     0xE1
#define RESET             0xFE

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int si7021_reset(int fd) {
    if (i2c_write_cmd(fd, RESET) < 0) return -1;
    usleep(15000);
    return 0;
}

static int si7021_read_measurement(int fd, uint8_t cmd, uint16_t *raw) {
    if (i2c_write_cmd(fd, cmd) < 0) return -1;
    usleep(20000);
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;
    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static float convert_temperature(uint16_t raw) {
    return (175.72f * raw / 65536.0f) - 46.85f;
}

static float convert_humidity(uint16_t raw) {
    float h = (125.0f * raw / 65536.0f) - 6.0f;
    if (h < 0.0f) h = 0.0f;
    if (h > 100.0f) h = 100.0f;
    return h;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (si7021_reset(fd) < 0) {
        fprintf(stderr, "Si7021 reset failed; device may be absent.\n");
        close(fd);
        return 1;
    }

    while (running) {
        uint16_t raw_t, raw_h;
        if (si7021_read_measurement(fd, MEASURE_TEMP_HOLD, &raw_t) < 0) {
            fprintf(stderr, "Temperature read failed.\n");
        } else if (si7021_read_measurement(fd, MEASURE_HUM_HOLD, &raw_h) < 0) {
            fprintf(stderr, "Humidity read failed.\n");
        } else {
            float temp = convert_temperature(raw_t);
            float hum  = convert_humidity(raw_h);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
            fflush(stdout);
        }
        sleep(5);
    }

    close(fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define CONFIG_REG     0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE    4.096
#define SAMPLE_DELAY   1
#define NUM_SAMPLES    3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write_reg16(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16 write(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16 read(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_init(int fd) {
    uint16_t config = 0x8483;  /* AIN0 single-ended, PGA 4.096V, 128 SPS, single-shot */
    if (i2c_write_reg16(fd, CONFIG_REG, config) != 0)
        return -1;
    return 0;
}

static int ads1115_read(int fd, int16_t *raw) {
    uint16_t val;
    if (i2c_read_reg16(fd, CONVERSION_REG, &val) != 0)
        return -1;
    *raw = (int16_t)val;
    return 0;
}

int main(void) {
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    if (ads1115_init(fd) != 0) {
        fprintf(stderr, "ADS1115 init failed (device may be absent or bus error)\n");
        goto cleanup;
    }

    for (int i = 0; i < NUM_SAMPLES && g_running; i++) {
        int16_t raw;
        if (ads1115_read(fd, &raw) != 0) {
            fprintf(stderr, "Read error on sample %d\n", i + 1);
            goto cleanup;
        }
        double voltage = (double)raw * REF_VOLTAGE / 32768.0;
        printf("Sample %d: %.4f V\n", i + 1, voltage);
        fflush(stdout);
        if (i < NUM_SAMPLES - 1 && g_running)
            sleep(SAMPLE_DELAY);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_PINS 6
static const unsigned int pins[NUM_PINS] = {8, 9, 10, 11, 23, 24};

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int vals[NUM_PINS] = {0, 1, 0, 1, 0, 1};
    int i;

    for (i = 0; i < NUM_PINS; i++) lines[i] = NULL;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %u\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "gpio-control", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %u\n", pins[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < 256 && running; i++) {
        for (int j = 0; j < NUM_PINS; j++) {
            int v = vals[j];
            if (gpiod_line_set_value(lines[j], v) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for pin %u\n", pins[j]);
                goto cleanup;
            }
            printf("Pin %u set to %d\n", pins[j], v);
            fflush(stdout);
            vals[j] = !v;
        }
        usleep(100000);
    }

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) gpiod_chip_close(chip);
    return (running || !i) ? EXIT_FAILURE : EXIT_SUCCESS;
}

