    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (pin 2)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (pin 3)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, "gpio-control", 0) < 0) {
        perror("gpiod_line_request_output (pin 2)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "gpio-control", 0) < 0) {
        perror("gpiod_line_request_output (pin 3)");
        goto cleanup;
    }

    for (int i = 0; i < NUM_CYCLES && keep_running; i++) {
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value (pin 2 high)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value (pin 3 high)");
