#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT11_PIN 4
#define MAX_TIMINGS 85

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht11(struct gpiod_line *line, float *temp, float *hum) {
    int data[5] = {0, 0, 0, 0, 0};
    int last = -1;
    int counter = 0;

    if (gpiod_line_request_output(line, "dht11", 1) < 0) {
        fprintf(stderr, "Failed to request line as output\n");
        return -1;
    }
    usleep(1000);
    gpiod_line_set_value(line, 0);
    usleep(20000);
    gpiod_line_set_value(line, 1);
    usleep(30);

    if (gpiod_line_request_input(line, "dht11") < 0) {
        fprintf(stderr, "Failed to request line as input\n");
        return -1;
    }

    for (int i = 0; i < MAX_TIMINGS && running; i++) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO value\n");
            return -1;
        }
        counter = 0;
        while (val == last) {
            counter++;
            usleep(1);
            if (counter == 255) break;
            val = gpiod_line_get_value(line);
            if (val < 0) return -1;
        }
        last = val;

        if (counter == 255) break;

        if ((i >= 4) && (i % 2 == 0)) {
            data[i / 2] = counter;
        }
    }

    if (!running) return -1;
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    *hum = (float)((data[0] << 8) + data[1]) / 10.0;
    *temp = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) *temp = -*temp;

    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, DHT11_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    float temp, hum;
    int rc = read_dht11(line, &temp, &hum);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    if (rc == 0) {
        printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp, hum);
        return 0;
    }

    fprintf(stderr, "Failed to read DHT11 sensor\n");
    return 1;
}

