#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOOP_DELAY_US 150000  /* 0.15 seconds */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_set_frequency(unsigned pin, unsigned freq) {
    if (gpioSetPWMfrequency(pin, freq) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%u, %u) failed\n", pin, freq);
        return -1;
    }
    return 0;
}

static int safe_set_range(unsigned pin, unsigned range) {
    if (gpioSetPWMrange(pin, range) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%u, %u) failed\n", pin, range);
        return -1;
    }
    return 0;
}

static int safe_pwm_write(unsigned pin, unsigned duty) {
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM(%u, %u) failed\n", pin, duty);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    /* Turn off all PWM outputs */
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (device may be absent)\n");
        return EXIT_FAILURE;
    }

    /* Configure PWM pins as outputs */
    if (safe_set_mode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        safe_set_mode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        safe_set_mode(PWM_PIN_3, PI_OUTPUT) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency and range */
    if (safe_set_frequency(PWM_PIN_1, PWM_FREQUENCY) != 0 ||
        safe_set_frequency(PWM_PIN_2, PWM_FREQUENCY) != 0 ||
        safe_set_frequency(PWM_PIN_3, PWM_FREQUENCY) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (safe_set_range(PWM_PIN_1, PWM_RANGE) != 0 ||
        safe_set_range(PWM_PIN_2, PWM_RANGE) != 0 ||
        safe_set_range(PWM_PIN_3, PWM_RANGE) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Main loop: apply PWM on each pin once every 0.15 seconds */
    while (running) {
        /* Duty cycle 0-255 for each pin */
        for (int duty = 0; duty <= PWM_RANGE && running; ++duty) {
            if (safe_pwm_write(PWM_PIN_1, (unsigned)duty) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            if (safe_pwm_write(PWM_PIN_2, (unsigned)duty) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            if (safe_pwm_write(PWM_PIN_3, (unsigned)duty) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            printf("PWM duty cycle: %d\n", duty);
            fflush(stdout);
            gpioDelay(LOOP_DELAY_US);
        }

        /* Reverse direction */
        for (int duty = PWM_RANGE; duty >= 0 && running; --duty) {
            if (safe_pwm_write(PWM_PIN_1, (unsigned)duty) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            if (safe_pwm_write(PWM_PIN_2, (unsigned)duty) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            if (safe_pwm_write(PWM_PIN_3, (unsigned)duty) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            printf("PWM duty cycle: %d\n", duty);
            fflush(stdout);
            gpioDelay(LOOP_DELAY_US);
        }
    }

    /* Clean shutdown */
    cleanup();
    return EXIT_SUCCESS;
}

