#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define OPT3001_ADDR 0x44
#define I2C_DEVICE "/dev/i2c-1"

#define REG_RESULT 0x00
#define REG_CONFIG 0x01

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write_reg16: write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write reg failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16: read failed: %s\n", strerror(errno));
        return -1;
    }
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X: %s\n", OPT3001_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    /*
     * Configuration register (0x01):
     *   RN[1:0]=11 (auto-range), CT=0 (100ms), M=00 (continuous),
     *   FL=00 (default), L=0 (default), POL=0 (default), ME=0 (default).
     * Value = 0xC003.
     */
    if (i2c_write_reg16(fd, REG_CONFIG, 0xC003) < 0) {
        close(fd);
        return 1;
    }

    /* Allow first conversion to complete (~100ms for auto-range). */
    usleep(150000);

    uint16_t raw;
    if (i2c_read_reg16(fd, REG_RESULT, &raw) < 0) {
        close(fd);
        return 1;
    }

    /*
     * Result register (0x00):
     *   Bits 15:12 = exponent, Bits 11:0 = mantissa.
     *   Result = mantissa * 2^exponent.
     */
    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;
    float result = (float)mantissa * (float)(1 << exponent);

    printf("OPT3001 Reading: %.2f lux\n", result);

    close(fd);
    return 0;
}

