    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for BCM 2 */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW (0) */
    ret = gpiod_line_request_output(line, "gpio-control", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Starting %d-cycle control on GPIO %d (BCM). Press Ctrl+C to exit.\n",
           NUM_CYCLES, GPIO_LINE_OFFSET);

    for (int cycle = 0; cycle < NUM_CYCLES && program_running; cycle++) {
        printf("Cycle %d/%d: setting GPIO %d HIGH\n", cycle + 1, NUM_CYCLES, GPIO_LINE_OFFSET);
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (HIGH)");
            break;
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int s = 0; s < CYCLE_DELAY_SEC && program_running; s++) {
            sleep(1);
        }

        if (!program_running) {
            break;
        }

        printf("Cycle %d/%d: setting GPIO %d LOW\n", cycle + 1, NUM_CYCLES, GPIO_LINE_OFFSET);
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (LOW)");
            break;
        }

        for (int s = 0; s < CYCLE_DELAY_SEC && program_running; s++) {
            sleep(1);
        }
    }

    /* Ensure the line is left LOW on exit */
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

