#include <gpiod.h>

#define BCM_PIN_1 5
#define BCM_PIN_2 17
#define BCM_PIN_3 24
#define CONSUMER "gpio-toggle"

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, BCM_PIN_1);
    line2 = gpiod_chip_get_line(chip, BCM_PIN_2);
    line3 = gpiod_chip_get_line(chip, BCM_PIN_3);
    if (!line1 || !line2 || !line3) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request each line as output, initial value LOW */
    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0 ||
        gpiod_line_request_output(line2, CONSUMER, 0) < 0 ||
        gpiod_line_request_output(line3, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("GPIO toggling started. Press Ctrl+C to exit.\n");

    while (running) {
        int v1 = gpiod_line_set_value(line1, 1);
        int v2 = gpiod_line_set_value(line2, 1);
        int v3 = gpiod_line_set_value(line3, 1);

        if (v1 < 0 || v2 < 0 || v3 < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        printf("GPIO %d, %d, %d HIGH\n", BCM_PIN_1, BCM_PIN_2, BCM_PIN_3);

        if (!running) break;
        usleep(200000); /* 0.2 s */

        v1 = gpiod_line_set_value(line1, 0);
        v2 = gpiod_line_set_value(line2, 0);
        v3 = gpiod_line_set_value(line3, 0);

        if (v1 < 0 || v2 < 0 || v3 < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        printf("GPIO %d, %d, %d LOW\n", BCM_PIN_1, BCM_PIN_2, BCM_PIN_3);

        if (!running) break;
        usleep(200000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip)  gpiod_chip_close(chip);

    printf("GPIO toggling stopped.\n");
    return ret;
}

