#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_OUT_1 2
#define GPIO_OUT_2 3
#define CONSUMER "gpio-toggle"

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line1 = gpiod_chip_get_line(chip, GPIO_OUT_1);
    if (line1 == NULL) {
        perror("gpiod_chip_get_line(2)");
        goto cleanup;
    }
    line2 = gpiod_chip_get_line(chip, GPIO_OUT_2);
    if (line2 == NULL) {
        perror("gpiod_chip_get_line(3)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value 0 */
    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(2)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(3)");
        goto cleanup;
    }

    /* Main loop: toggle each line once every 0.1 s */
    while (running) {
        int v1 = gpiod_line_get_value(line1);
        int v2 = gpiod_line_get_value(line2);

        if (v1 < 0) {
            perror("gpiod_line_get_value(2)");
            goto cleanup;
        }
        if (v2 < 0) {
            perror("gpiod_line_get_value(3)");
            goto cleanup;
        }

        int new_v1 = (v1 == 0) ? 1 : 0;
        int new_v2 = (v2 == 0) ? 1 : 0;

        if (gpiod_line_set_value(line1, new_v1) < 0) {
            perror("gpiod_line_set_value(2)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, new_v2) < 0) {
            perror("gpiod_line_set_value(3)");
            goto cleanup;
        }

        printf("GPIO 2: %d, GPIO 3: %d\n", new_v1, new_v2);
        fflush(stdout);

        /* Sleep 0.1 s; interruptible by signals */
        for (int i = 0; i < 10 && running; i++) {
            usleep(100000); /* 100 ms */
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line1 != NULL) {
        gpiod_line_release(line1);
    }
    if (line2 != NULL) {
        gpiod_line_release(line2);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

