        return EXIT_FAILURE;
    }

    line4 = gpiod_chip_get_line(chip, GPIO_4);
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line4 || !line17) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line4, "gpio-4-output", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 4)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line17, "gpio-17-output", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 17)");
        goto cleanup;
    }

    printf("GPIO 4 and GPIO 17 set to HIGH.\n");
    fflush(stdout);

    if (gpiod_line_set_value(line4, 1) < 0) {
        perror("gpiod_line_set_value (GPIO 4)");
        goto cleanup;
    }
    if (gpiod_line_set_value(line17, 1) < 0) {
        perror("gpiod_line_set_value (GPIO 17)");
        goto cleanup;
    }

    while (running) {
        sleep(1);
    }

    printf("\nExiting, restoring GPIO 4 and GPIO 17 to LOW.\n");
    fflush(stdout);

    gpiod_line_set_value(line4, 0);
    gpiod_line_set_value(line17, 0);
    ret = EXIT_SUCCESS;

cleanup:
    if (line4)  gpiod_line_release(line4);
    if (line17) gpiod_line_release(line17);
    if (chip)   gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 2
#define NUM_CYCLES 3
#define CYCLE_DELAY_US 100000  /* 0.1 seconds */

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Apply output state in a loop */
    for (int i = 0; i < NUM_CYCLES && keep_running; i++) {
        int val = (i % 2 == 0) ? 1 : 0;
        ret = gpiod_line_set_value(line, val);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        printf("Cycle %d: GPIO %d set to %d\n", i + 1, GPIO_LINE_OFFSET, val);
        fflush(stdout);
        usleep(CYCLE_DELAY_US);
    }

    /* Clean up: set line LOW and release resources */
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 12
#define PWM_PIN_3 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_set_frequency(unsigned pin, unsigned freq) {
    if (gpioSetPWMfrequency(pin, freq) != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%u, %u) failed\n", pin, freq);
        return -1;
    }
    return 0;
}

static int safe_set_range(unsigned pin, unsigned range) {
    if (gpioSetPWMrange(pin, range) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%u, %u) failed\n", pin, range);
        return -1;
    }
    return 0;
}

static int safe_pwm_write(unsigned pin, unsigned duty) {
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM(%u, %u) failed\n", pin, duty);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    unsigned pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    const int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    for (int i = 0; i < num_pins; i++) {
        if (safe_set_mode(pins[i], PI_OUTPUT) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (safe_set_frequency(pins[i], PWM_FREQUENCY) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (safe_set_range(pins[i], PWM_RANGE) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    int duty = 0;
    while (running) {
        for (int i = 0; i < num_pins; i++) {
            if (safe_pwm_write(pins[i], duty) != 0) {
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("PWM duty cycle: %d\n", duty);
        fflush(stdout);

        duty = (duty + 1) % (PWM_RANGE + 1);

        if (duty == 0) {
            break;
        }
        sleep(1);
    }

    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

