    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get lines */
    line1 = gpiod_chip_get_line(chip, GPIO_OUT_1);
    if (!line1) {
        perror("gpiod_chip_get_line (17)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_OUT_2);
    if (!line2) {
        perror("gpiod_chip_get_line (18)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initial value 0 */
    ret = gpiod_line_request_output(line1, "gpio-toggle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (17)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
