static void cleanup(void) {
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        safe_set_mode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        safe_set_mode(PWM_PIN_3, PI_OUTPUT) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (safe_set_frequency(PWM_PIN_1, PWM_FREQ) != 0 ||
        safe_set_frequency(PWM_PIN_2, PWM_FREQ) != 0 ||
        safe_set_frequency(PWM_PIN_3, PWM_FREQ) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (safe_set_range(PWM_PIN_1, PWM_RANGE) != 0 ||
        safe_set_range(PWM_PIN_2, PWM_RANGE) != 0 ||
        safe_set_range(PWM_PIN_3, PWM_RANGE) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        for (int duty = 0; duty <= PWM_RANGE && running; duty += 10) {
            if (safe_pwm_write(PWM_PIN_1, duty) != 0 ||
                safe_pwm_write(PWM_PIN_2, duty) != 0 ||
                safe_pwm_write(PWM_PIN_3, duty) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            printf("PWM duty cycle: %d/%d\n", duty, PWM_RANGE);
            fflush(stdout);
            gpioDelay(500000);
        }
        for (int duty = PWM_RANGE; duty >= 0 && running; duty -= 10) {
            if (safe_pwm_write(PWM_PIN_1, duty) != 0 ||
                safe_pwm_write(PWM_PIN_2, duty) != 0 ||
                safe_pwm_write(PWM_PIN_3, duty) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            printf("PWM duty cycle: %d/%d\n", duty, PWM_RANGE);
