            gpioDelay(500000);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices"
#define W1_SLAVE_FILE  "w1_slave"
#define MAX_DEVICES    10
#define MAX_PATH_LEN   256
#define MAX_LINE_LEN   256

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int find_w1_devices(char paths[][MAX_PATH_LEN], int max_count) {
    FILE *fp;
    char line[MAX_LINE_LEN];
    int count = 0;

    fp = popen("ls -d " W1_DEVICES_DIR "/* 2>/dev/null", "r");
    if (!fp) {
        fprintf(stderr, "Error: cannot list w1 devices: %s\n", strerror(errno));
        return -1;
    }

    while (fgets(line, sizeof(line), fp) != NULL && count < max_count) {
        size_t len = strlen(line);
        if (len > 0 && line[len - 1] == '\n') line[len - 1] = '\0';
        if (len > 0 && line[len - 1] == '\r') line[len - 1] = '\0';

        if (snprintf(paths[count], MAX_PATH_LEN, "%s/%s", W1_DEVICES_DIR, line) >= MAX_PATH_LEN) {
            fprintf(stderr, "Error: path too long, skipping\n");
            continue;
        }
        count++;
    }

    if (pclose(fp) == -1) {
        fprintf(stderr, "Warning: popen close failed: %s\n", strerror(errno));
    }

    return count;
}

static int read_temperature(const char *device_path, float *temperature) {
    char file_path[MAX_PATH_LEN];
    FILE *fp;
    char line1[MAX_LINE_LEN];
    char line2[MAX_LINE_LEN];

    if (snprintf(file_path, sizeof(file_path), "%s/%s", device_path, W1_SLAVE_FILE) >= (int)sizeof(file_path)) {
        fprintf(stderr, "Error: file path too long\n");
        return -1;
    }

    fp = fopen(file_path, "r");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", file_path, strerror(errno));
        return -1;
    }

    if (!fgets(line1, sizeof(line1), fp)) {
        fprintf(stderr, "Error: failed to read first line from %s\n", file_path);
        fclose(fp);
        return -1;
    }

    if (!fgets(line2, sizeof(line2), fp)) {
        fprintf(stderr, "Error: failed to read second line from %s\n", file_path);
        fclose(fp);
        return -1;
    }

    fclose(fp);

    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "Error: CRC check failed for %s\n", device_path);
        return -1;
    }

    char *temp_str = strstr(line2, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Error: temperature data not found in %s\n", device_path);
        return -1;
    }

    errno = 0;
    char *endptr = NULL;
    long millideg = strtol(temp_str + 2, &endptr, 10);
    if (errno != 0 || endptr == temp_str + 2) {
        fprintf(stderr, "Error: invalid temperature data in %s\n", device_path);
        return -1;
    }

    *temperature = (float)millideg / 1000.0f;
    return 0;
}

int main(void) {
    char device_paths[MAX_DEVICES][MAX_PATH_LEN];
    int num_devices;
    int i;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: cannot install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    num_devices = find_w1_devices(device_paths, MAX_DEVICES);
    if (num_devices < 0) {
        return 1;
    }

    if (num_devices == 0) {
        fprintf(stderr, "Error: no DS18B20 devices found in %s\n", W1_DEVICES_DIR);
        return 1;
    }

    printf("Found %d DS18B20 device(s):\n", num_devices);
    for (i = 0; i < num_devices; i++) {
        printf("  [%d] %s\n", i + 1, device_paths[i]);
    }
    printf("\n");

    while (g_running) {
        for (i = 0; i < num_devices; i++) {
            float temperature;
            if (read_temperature(device_paths[i], &temperature) == 0) {
                printf("[%d] %s: %.2f °C\n", i + 1, device_paths[i], temperature);
            } else {
                fprintf(stderr, "[%d] %s: read failed\n", i + 1, device_paths[i]);
            }
        }
        printf("\n");
        fflush(stdout);

        if (g_running) {
            sleep(5);
        }
    }

    printf("\nExiting cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HTU21D_ADDR 0x40
#define I2C_DEVICE "/dev/i2c-1"
#define MEASURE_TEMP_HOLD 0xE3
#define MEASURE_HUM_HOLD  0xE5
#define SOFT_RESET       0xFE

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int htu21d_reset(int fd) {
    if (i2c_write_cmd(fd, SOFT_RESET) < 0) return -1;
    usleep(15000);
    return 0;
}

static int htu21d_read_raw(int fd, uint8_t cmd, uint16_t *raw) {
    if (i2c_write_cmd(fd, cmd) < 0) return -1;
    usleep(50000);

    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, 3) < 0) return -1;

    if (buf[2] & 0x02) {
        fprintf(stderr, "HTU21D busy after command 0x%02X\n", cmd);
        return -1;
    }

    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    *raw &= 0xFFFC;
    return 0;
}

static float convert_temperature(uint16_t raw) {
    return -46.85 + 175.72 * ((float)raw / 65536.0);
}

static float convert_humidity(uint16_t raw) {
    float h = -6.0 + 125.0 * ((float)raw / 65536.0);
    if (h < 0.0f) h = 0.0f;
    if (h > 100.0f) h = 100.0f;
    return h;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", HTU21D_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (htu21d_reset(fd) < 0) {
        fprintf(stderr, "HTU21D soft reset failed\n");
        close(fd);
        return 1;
    }

    while (running) {
        uint16_t raw_t, raw_h;

        if (htu21d_read_raw(fd, MEASURE_TEMP_HOLD, &raw_t) < 0) {
            fprintf(stderr, "Temperature read failed\n");
        } else if (htu21d_read_raw(fd, MEASURE_HUM_HOLD, &raw_h) < 0) {
            fprintf(stderr, "Humidity read failed\n");
        } else {
            float temp = convert_temperature(raw_t);
            float hum  = convert_humidity(raw_h);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
            fflush(stdout);
        }

        for (int i = 0; i < 60 && running; i++) {
            sleep(1);
        }
    }

    close(fd);
    return 0;
}

