        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, BCM_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (pin 4)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, BCM_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (pin 18)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initial value LOW */
    ret = gpiod_line_request_output(line1, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (pin 4)");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line2, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (pin 18)");
        goto cleanup;
    }

    printf("Starting GPIO toggling on BCM pins %d and %d. Press Ctrl+C to exit.\n",
           BCM_PIN_1, BCM_PIN_2);
    fflush(stdout);

    while (running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0) {
            perror("gpiod_line_get_value (pin 4)");
            break;
        }
        if (val2 < 0) {
            perror("gpiod_line_get_value (pin 18)");
            break;
        }

        int new_val1 = (val1 == 0) ? 1 : 0;
        int new_val2 = (val2 == 0) ? 1 : 0;

        ret = gpiod_line_set_value(line1, new_val1);
        if (ret < 0) {
            perror("gpiod_line_set_value (pin 4)");
            break;
        }
        ret = gpiod_line_set_value(line2, new_val2);
        if (ret < 0) {
            perror("gpiod_line_set_value (pin 18)");
            break;
        }

        printf("GPIO %d: %d, GPIO %d: %d\n",
               BCM_PIN_1, new_val1, BCM_PIN_2, new_val2);
        fflush(stdout);

        usleep(50000); /* 0.05 seconds */
    }

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip)  gpiod_chip_close(chip);

    printf("\nGPIO toggling stopped. Resources released.\n");
    return (ret < 0) ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
