#include <gpiod.h>

#define BCM_PIN_1 2
#define BCM_PIN_2 3
#define CONSUMER "gpio-toggle"
#define CHIP_NAME "gpiochip0"

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line1 = gpiod_chip_get_line(chip, BCM_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (pin 2)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, BCM_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (pin 3)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initial value 0 */
    ret = gpiod_line_request_output(line1, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (pin 2)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line2, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (pin 3)");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: toggle each line once every 2 seconds */
    while (running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0) {
            perror("gpiod_line_get_value (pin 2)");
            break;
        }
        if (val2 < 0) {
            perror("gpiod_line_get_value (pin 3)");
            break;
        }

        int new1 = (val1 == 0) ? 1 : 0;
        int new2 = (val2 == 0) ? 1 : 0;

        ret = gpiod_line_set_value(line1, new1);
        if (ret < 0) {
            perror("gpiod_line_set_value (pin 2)");
            break;
