        printf("GPIO %d: %d, GPIO %d: %d\n", BCM_PIN_1, new1, BCM_PIN_2, new2);
        fflush(stdout);

        /* Sleep 2 seconds, but wake early if interrupted */
        for (int i = 0; i < 20 && running; i++) {
            usleep(100000); /* 100 ms */
        }
    }

    /* Clean shutdown: set both lines low and release resources */
    if (line1) {
        gpiod_line_set_value(line1, 0);
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_set_value(line2, 0);
        gpiod_line_release(line2);
    }
    if (chip) {
