#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define DHT22_PIN 17
#define NUM_PINS 4

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = { us / 1000000, (long)(us % 1000000) * 1000 };
    nanosleep(&ts, NULL);
}

static void sleep_ms(unsigned int ms) {
    sleep_us(ms * 1000);
}

static int wait_level(struct gpiod_line *line, int target, unsigned int timeout_us) {
    unsigned int elapsed = 0;
    while (gpiod_line_get_value(line) != target) {
        if (elapsed >= timeout_us) return -1;
        sleep_us(1);
        elapsed++;
    }
    return 0;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    int data[5] = {0, 0, 0, 0, 0};
    int last = -1;

    if (gpiod_line_request_output(line, "dht22", 1) < 0) return -1;
    sleep_ms(1);
    gpiod_line_set_value(line, 0);
    sleep_us(2000);
    gpiod_line_set_value(line, 1);
    sleep_us(30);

    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    if (wait_level(line, 0, 100) < 0) return -1;
    if (wait_level(line, 1, 100) < 0) return -1;
    if (wait_level(line, 0, 100) < 0) return -1;

    for (int i = 0; i < 40; i++) {
        if (wait_level(line, 1, 100) < 0) return -1;
        unsigned int high_us = 0;
        while (gpiod_line_get_value(line) == 1) {
            high_us++;
            sleep_us(1);
            if (high_us > 100) return -1;
        }
        if (high_us > 50) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return -1;
    }

    *hum = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temp = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) *temp = -*temp;

    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sighandler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    struct gpiod_line *lines[NUM_PINS];
    int pins[NUM_PINS] = {DHT22_PIN, 22, 23, 24};

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO %d\n", pins[i]);
            for (int j = 0; j < i; j++) gpiod_line_release(lines[j]);
            gpiod_chip_close(chip);
            return 1;
        }
    }

    while (running) {
        float temp, hum;
        int err = 0;

        for (int i = 0; i < NUM_PINS; i++) {
            if (read_dht22(lines[i], &temp, &hum) == 0) {
                printf("GPIO %d: Temp=%.1fC, Hum=%.1f%%\n", pins[i], temp, hum);
            } else {
                fprintf(stderr, "GPIO %d: DHT22 read error\n", pins[i]);
                err = 1;
            }
        }

        if (err) {
            fprintf(stderr, "DHT22 read error on all pins. Exiting.\n");
            break;
        }

        sleep(2);
    }

    for (int i = 0; i < NUM_PINS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27
#define PWM_RANGE 1000
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned pin) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u) failed\n", pin);
        return -1;
    }
    return 0;
}

static int safe_set_frequency(unsigned pin, unsigned freq) {
    if (gpioSetPWMfrequency(pin, freq) != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%u, %u) failed\n", pin, freq);
        return -1;
    }
    return 0;
}

static int safe_set_range(unsigned pin, unsigned range) {
    if (gpioSetPWMrange(pin, range) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%u, %u) failed\n", pin, range);
        return -1;
    }
    return 0;
}

static int safe_pwm_write(unsigned pin, unsigned duty) {
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM(%u, %u) failed\n", pin, duty);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(PWM_PIN_1) != 0 ||
        safe_set_mode(PWM_PIN_2) != 0 ||
        safe_set_mode(PWM_PIN_3) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (safe_set_frequency(PWM_PIN_1, PWM_FREQ) != 0 ||
        safe_set_frequency(PWM_PIN_2, PWM_FREQ) != 0 ||
        safe_set_frequency(PWM_PIN_3, PWM_FREQ) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (safe_set_range(PWM_PIN_1, PWM_RANGE) != 0 ||
        safe_set_range(PWM_PIN_2, PWM_RANGE) != 0 ||
        safe_set_range(PWM_PIN_3, PWM_RANGE) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    unsigned duty = 0;
    while (running) {
        if (safe_pwm_write(PWM_PIN_1, duty) != 0 ||
            safe_pwm_write(PWM_PIN_2, duty) != 0 ||
            safe_pwm_write(PWM_PIN_3, duty) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
        printf("PWM duty cycle: %u/%u\n", duty, PWM_RANGE);
        fflush(stdout);

        duty = (duty + 100) % (PWM_RANGE + 1);
        time_sleep(0.5);
    }

    cleanup();
    return EXIT_SUCCESS;
