        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_OUT_18);
    if (!line18) {
        perror("gpiod_chip_get_line(18)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initial value 0 */
    ret = gpiod_line_request_output(line17, "gpio-control", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(17)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line18, "gpio-control", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(18)");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: toggle each line once every second */
    while (keep_running) {
        int val17 = gpiod_line_get_value(line17);
        int val18 = gpiod_line_get_value(line18);

        if (val17 < 0) {
            perror("gpiod_line_get_value(17)");
