#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80

#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { (uint8_t)(TCS34725_COMMAND_BIT | reg), value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | reg);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "Error reading %zu bytes from register 0x%02X: %s\n", len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int tcs34725_init(int fd) {
    if (i2c_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) return -1;
    usleep(3000);
    if (i2c_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) return -1;
    if (i2c_write_byte(fd, TCS34725_ATIME, 0xFF) < 0) return -1;
    if (i2c_write_byte(fd, TCS34725_CONTROL, 0x01) < 0) return -1;
    return 0;
}

static int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buf[8];
    if (i2c_read_block(fd, TCS34725_CDATA, buf, 8) < 0) return -1;
    *clear = (uint16_t)((buf[1] << 8) | buf[0]);
    *red   = (uint16_t)((buf[3] << 8) | buf[2]);
    *green = (uint16_t)((buf[5] << 8) | buf[4]);
    *blue  = (uint16_t)((buf[7] << 8) | buf[6]);
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", TCS34725_ADDRESS, strerror(errno));
        goto cleanup;
    }

    uint8_t id;
    if (i2c_read_block(fd, TCS34725_ID, &id, 1) < 0) {
        fprintf(stderr, "TCS34725 not detected at address 0x%02X\n", TCS34725_ADDRESS);
        goto cleanup;
    }
    if (id != 0x44 && id != 0x4D) {
        fprintf(stderr, "Unexpected TCS34725 ID: 0x%02X (expected 0x44 or 0x4D)\n", id);
        goto cleanup;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "Error initializing TCS34725\n");
        goto cleanup;
    }

    printf("TCS34725 initialized. Reading every 0.2 seconds. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t clear, red, green, blue;
        if (tcs34725_read_data(fd, &clear, &red, &green, &blue) < 0) {
            fprintf(stderr, "Error reading sensor data\n");
            goto cleanup;
        }
        printf("Clear: %5u, Red: %5u, Green: %5u, Blue: %5u\n", clear, red, green, blue);
        usleep(200000);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        i2c_write_byte(fd, TCS34725_ENABLE, 0x00);
        close(fd);
    }
    return ret;
}

