 * Write a single pixel to the strip.
 * pigpio's gpioWrite takes a level (0 or 1) and a tick delay.
 * We use a 1-element array for the level so gpioWrite can take a pointer.
 */
static void set_pixel(int pin, int r, int g, int b) {
    int levels[1] = { (r + g + b) / 3 };
    gpioWrite(pin, levels[0]);
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (device not ready?)\n");
        return EXIT_FAILURE;
    }

    /* Configure the pixel pin as output */
    if (gpioSetMode(PIXEL_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PIXEL_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Main loop: apply a single colour to each pixel once per iteration */
    while (running) {
        for (int i = 0; i < NUM_PIXELS && running; i++) {
            set_pixel(PIXEL_PIN, 255, 0, 0);  /* Red */
            gpioDelay(DELAY_US);
        }
    }

    /* Clean shutdown: turn off the strip and release pigpio */
    gpioWrite(PIXEL_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

