#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define LCD_ADDR 0x27
#define I2C_DEVICE "/dev/i2c-1"

#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME 0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_FUNCTIONSET 0x20
#define LCD_SETDDRAMADDR 0x80

#define LCD_ENTRYLEFT 0x02
#define LCD_ENTRYSHIFTDECREMENT 0x00
#define LCD_DISPLAYON 0x04
#define LCD_CURSOROFF 0x00
#define LCD_BLINKOFF 0x00
#define LCD_4BITMODE 0x00
#define LCD_2LINE 0x08
#define LCD_5x8DOTS 0x00

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t val) {
    if (write(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int lcd_send_byte(int fd, uint8_t val, uint8_t mode) {
    uint8_t high = mode | (val & 0xF0) | LCD_BACKLIGHT;
    uint8_t low = mode | ((val << 4) & 0xF0) | LCD_BACKLIGHT;

    if (i2c_write_byte(fd, high) < 0) return -1;
    usleep(1000);
    if (i2c_write_byte(fd, low) < 0) return -1;
    usleep(1000);
    return 0;
}

static int lcd_send_command(int fd, uint8_t cmd) {
    return lcd_send_byte(fd, cmd, 0);
}

static int lcd_send_data(int fd, uint8_t data) {
    return lcd_send_byte(fd, data, LCD_BACKLIGHT);
}

static int lcd_init(int fd) {
    usleep(50000);

    if (lcd_send_command(fd, 0x33) < 0) return -1;
    usleep(5000);
    if (lcd_send_command(fd, 0x32) < 0) return -1;
    usleep(5000);

    if (lcd_send_command(fd, LCD_FUNCTIONSET | LCD_4BITMODE | LCD_2LINE | LCD_5x8DOTS) < 0) return -1;
    usleep(5000);

    if (lcd_send_command(fd, LCD_DISPLAYCONTROL | LCD_DISPLAYON | LCD_CURSOROFF | LCD_BLINKOFF) < 0) return -1;
    usleep(5000);

    if (lcd_send_command(fd, LCD_CLEARDISPLAY) < 0) return -1;
    usleep(2000);

    if (lcd_send_command(fd, LCD_ENTRYMODESET | LCD_ENTRYLEFT | LCD_ENTRYSHIFTDECREMENT) < 0) return -1;
    usleep(5000);

    return 0;
}

static int lcd_clear(int fd) {
    return lcd_send_command(fd, LCD_CLEARDISPLAY);
}

static int lcd_set_cursor(int fd, int row, int col) {
    uint8_t addr = (row == 0) ? 0x00 : 0x40;
    addr += col;
    return lcd_send_command(fd, LCD_SETDDRAMADDR | addr);
}

static int lcd_write_string(int fd, const char *str) {
    for (int i = 0; str[i] != '\0'; i++) {
        if (lcd_send_data(fd, (uint8_t)str[i]) < 0) return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, LCD_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LCD_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (lcd_init(fd) < 0) {
        fprintf(stderr, "LCD initialization failed\n");
        close(fd);
        return 1;
    }

    while (running) {
        if (lcd_clear(fd) < 0) break;
        if (lcd_set_cursor(fd, 0, 0) < 0) break;
        if (lcd_write_string(fd, "Hello, World!") < 0) break;
        if (lcd_set_cursor(fd, 1, 0) < 0) break;
        if (lcd_write_string(fd, "Raspberry Pi") < 0) break;

        for (int i = 0; i < 10 && running; i++) {
            sleep(1);
        }
    }

    close(fd);
    return 0;
}

