#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_OUT_14 14
#define GPIO_OUT_15 15
#define CONSUMER "gpio-output-toggle"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line14 = NULL;
    struct gpiod_line *line15 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the lines */
    line14 = gpiod_chip_get_line(chip, GPIO_OUT_14);
    if (line14 == NULL) {
        perror("gpiod_chip_get_line(14)");
        goto cleanup;
    }

    line15 = gpiod_chip_get_line(chip, GPIO_OUT_15);
    if (line15 == NULL) {
        perror("gpiod_chip_get_line(15)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value 0 */
    if (gpiod_line_request_output(line14, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(14)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line15, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(15)");
        goto cleanup;
    }

    printf("GPIO 14 and GPIO 15 toggled every %d seconds. Press Ctrl+C to exit.\n",
           POLL_INTERVAL_SEC);
    fflush(stdout);

    int val14 = 0;
    int val15 = 0;

    while (keep_running) {
        val14 = !val14;
        val15 = !val15;

        if (gpiod_line_set_value(line14, val14) < 0) {
            perror("gpiod_line_set_value(14)");
            goto cleanup;
        }

        if (gpiod_line_set_value(line15, val15) < 0) {
            perror("gpiod_line_set_value(15)");
            goto cleanup;
        }

        printf("GPIO 14: %d, GPIO 15: %d\n", val14, val15);
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line14 != NULL) {
        gpiod_line_release(line14);
    }
    if (line15 != NULL) {
        gpiod_line_release(line15);
    }
