#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 22
#define ALARM_PIN 27

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {
        .tv_sec = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

static void trigger_sensor(struct gpiod_line *trig) {
    gpiod_line_set_value(trig, 1);
    sleep_us(10);
    gpiod_line_set_value(trig, 0);
}

static double measure_distance(struct gpiod_line *echo) {
    long long t0, t1;

    t0 = now_us();
    while (gpiod_line_get_value(echo) == 0) {
        if (now_us() - t0 > TIMEOUT_US) return -1.0;
    }
    t0 = now_us();

    while (gpiod_line_get_value(echo) == 1) {
        if (now_us() - t0 > TIMEOUT_US) return -1.0;
    }
    t1 = now_us();

    double elapsed = (double)(t1 - t0) / 1000000.0;
    return elapsed * SPEED_OF_SOUND / 2.0;
}

static void set_alarm(struct gpiod_line *alarm, int state) {
    gpiod_line_set_value(alarm, state);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *alarm = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    alarm = gpiod_chip_get_line(chip, ALARM_PIN);
    if (!trig || !echo || !alarm) {
        fprintf(stderr, "Failed to acquire GPIO lines\n");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("request_output trig");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("request_input echo");
        goto cleanup;
    }
    if (gpiod_line_request_output(alarm, "hc-sr04-alarm", 0) < 0) {
        perror("request_output alarm");
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_sensor(trig);
        double distance = measure_distance(echo);

        if (distance < 0.0) {
            fprintf(stderr, "Error: Sensor timeout or no echo.\n");
            set_alarm(alarm, 0);
        } else if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Warning: Distance out of range (%.2f cm).\n", distance);
            set_alarm(alarm, 1);
        } else {
            printf("Distance: %.2f cm\n", distance);
            set_alarm(alarm, 0);
        }

        sleep_us(100000);
    }

    printf("\nExiting gracefully...\n");
    set_alarm(alarm, 0);
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (alarm) gpiod_line_release(alarm);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for BCM 17 */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW (0) */
    ret = gpiod_line_request_output(line, "gpio-17-toggle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO 17 toggling every 1 second. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        val = !val;
        ret = gpiod_line_set_value(line, val);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO 17 set to %d\n", val);
        sleep(1);
    }

    /* Clean up: release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nGPIO 17 released. Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_18 18
#define GPIO_24 24

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line18 = NULL;
    struct gpiod_line *line24 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line(18)");
        goto cleanup;
    }

    line24 = gpiod_chip_get_line(chip, GPIO_24);
    if (!line24) {
        perror("gpiod_chip_get_line(24)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line18, "gpio-control", 0) < 0) {
        perror("gpiod_line_request_output(18)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line24, "gpio-control", 0) < 0) {
        perror("gpiod_line_request_output(24)");
        goto cleanup;
    }

    printf("GPIO 18 and GPIO 24 set to output, both initially LOW.\n");
    fflush(stdout);

    while (running) {
        if (gpiod_line_set_value(line18, 1) < 0) {
            perror("gpiod_line_set_value(18, 1)");
            break;
        }
        if (gpiod_line_set_value(line24, 1) < 0) {
            perror("gpiod_line_set_value(24, 1)");
            break;
        }
        usleep(500000);

        if (!running) break;

        if (gpiod_line_set_value(line18, 0) < 0) {
            perror("gpiod_line_set_value(18, 0)");
            break;
        }
        if (gpiod_line_set_value(line24, 0) < 0) {
            perror("gpiod_line_set_value(24, 0)");
            break;
        }
        usleep(500000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line18) gpiod_line_release(line18);
    if (line24) gpiod_line_release(line24);
    if (chip)   gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_2   2
#define GPIO_3   3
#define GPIO_23  23
#define CONSUMER "gpio-toggle"

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line2 = NULL, *line3 = NULL, *line23 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line2  = gpiod_chip_get_line(chip, GPIO_2);
    line3  = gpiod_chip_get_line(chip, GPIO_3);
    line23 = gpiod_chip_get_line(chip, GPIO_23);
    if (!line2 || !line3 || !line23) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request each line as output, initial value LOW */
    ret = gpiod_line_request_output(line2, CONSUMER, 0);
    if (ret < 0) { perror("gpiod_line_request_output GPIO 2"); goto cleanup; }
    ret = gpiod_line_request_output(line3, CONSUMER, 0);
    if (ret < 0) { perror("gpiod_line_request_output GPIO 3"); goto cleanup; }
    ret = gpiod_line_request_output(line23, CONSUMER, 0);
    if (ret < 0) { perror("gpiod_line_request_output GPIO 23"); goto cleanup; }

    printf("GPIO 2, 3, 23 toggled every 2 seconds. Press Ctrl+C to exit.\n");

    while (running) {
        int v2 = gpiod_line_get_value(line2);
        int v3 = gpiod_line_get_value(line3);
        int v23 = gpiod_line_get_value(line23);

        if (v2 < 0 || v3 < 0 || v23 < 0) {
            fprintf(stderr, "Error reading GPIO values\n");
            break;
        }

        printf("GPIO 2=%d, GPIO 3=%d, GPIO 23=%d\n", v2, v3, v23);

        /* Toggle each line */
        ret = gpiod_line_set_value(line2,  v2 ? 0 : 1);
        if (ret < 0) { perror("gpiod_line_set_value GPIO 2"); break; }
        ret = gpiod_line_set_value(line3,  v3 ? 0 : 1);
        if (ret < 0) { perror("gpiod_line_set_value GPIO 3"); break; }
        ret = gpiod_line_set_value(line23, v23 ? 0 : 1);
        if (ret < 0) { perror("gpiod_line_set_value GPIO 23"); break; }

        /* Sleep 2 seconds, but wake early if interrupted */
        for (int i = 0; i < 20 && running; i++)
            usleep(100000);
    }

cleanup:
    /* Release lines and close chip */
    if (line2)  gpiod_line_release(line2);
    if (line3)  gpiod_line_release(line3);
    if (line23) gpiod_line_release(line23);
    if (chip)   gpiod_chip_close(chip);

    printf("\nResources released. Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://mqtt.example.com:1883"
#define MQTT_TOPIC "sensor/data"
#define MQTT_CLIENT_ID "rpi_sensor"
#define MQTT_USERNAME "username"
#define MQTT_PASSWORD "password"
#define SENSOR_DATA_FILE "/home/pi/sensor_data.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(const char *filename, char *buffer, size_t bufsize) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    if (fgets(buffer, (int)bufsize, fp) == NULL) {
        fprintf(stderr, "Error reading from file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static int publish_mqtt_message(MQTTClient *client, const char *topic, const char *payload) {
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    int rc;

    pubmsg.payload = (void *)payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = 1;
    pubmsg.retained = 0;

    rc = MQTTClient_publishMessage(client, topic, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        return -1;
    }

    rc = MQTTClient_waitForCompletion(client, token, 1000);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to wait for publish completion, return code %d\n", rc);
        return -1;
    }

    return 0;
}

int main(void) {
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_SSLOptions ssl_opts = MQTTClient_SSLOptions_initializer;
    int rc;
    char sensor_data[256];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    ssl_opts.enableServerCertValidation = true;
    conn_opts.ssl = &ssl_opts;
    conn_opts.username = MQTT_USERNAME;
    conn_opts.password = MQTT_PASSWORD;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    rc = MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client, return code %d\n", rc);
        gpioTerminate();
        return 1;
    }

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    if (read_sensor_data(SENSOR_DATA_FILE, sensor_data, sizeof(sensor_data)) != 0) {
        fprintf(stderr, "Sensor data not available. Exiting.\n");
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    if (publish_mqtt_message(&client, MQTT_TOPIC, sensor_data) != 0) {
        fprintf(stderr, "Failed to publish sensor data\n");
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    printf("Sensor data published successfully: %s\n", sensor_data);

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define STEP_DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGTERM handler.\n");
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty = 0;
    while (running) {
        if (gpioPWM(PWM_PIN, duty) != 0) {
            fprintf(stderr, "Error: failed to set PWM duty cycle on GPIO %d.\n", PWM_PIN);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        printf("PWM duty cycle set to %d/%d on GPIO %d\n", duty, PWM_RANGE, PWM_PIN);
        fflush(stdout);

        duty = (duty + 1) % (PWM_RANGE + 1);

        if (running) {
            gpioDelay(STEP_DELAY_US);
        }
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define CHIP_NAME "gpiochip0"
#define TIMEOUT_US 30000  /* 30 ms timeout for echo */
#define LOOP_DELAY_US 200000 /* 0.2 s between readings */

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure distance in cm. Returns -1.0 on timeout or error.
 * Uses busy-wait with microsecond precision; not suitable for production.
 */
static float measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    struct timespec ts_start, ts_end;
    long elapsed_us;

    /* Ensure trigger is low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("Failed to set trigger low");
        return -1.0f;
    }
    usleep(2);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("Failed to set trigger high");
        return -1.0f;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("Failed to set trigger low");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout) */
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    while (gpiod_line_get_value(echo) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &ts_end);
        elapsed_us = (ts_end.tv_sec - ts_start.tv_sec) * 1000000L +
                     (ts_end.tv_nsec - ts_start.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return -1.0f;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &ts_start);

    /* Wait for echo falling edge (timeout) */
    while (gpiod_line_get_value(echo) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &ts_end);
        elapsed_us = (ts_end.tv_sec - ts_start.tv_sec) * 1000000L +
                     (ts_end.tv_nsec - ts_start.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1.0f;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &ts_end);

    elapsed_us = (ts_end.tv_sec - ts_start.tv_sec) * 1000000L +
                 (ts_end.tv_nsec - ts_start.tv_nsec) / 1000L;

    /* Speed of sound: 343 m/s = 0.0343 cm/us */
    return (float)elapsed_us * 0.0343f / 2.0f;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("Failed to get trigger line");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("Failed to get echo line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("Failed to request trigger line as output");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("Failed to request echo line as input");
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance(trig, echo);
        if (distance >= 0.0f) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Measurement failed\n");
        }
        usleep(LOOP_DELAY_US);
    }

    printf("\nExiting cleanly...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 23

#define PWM_RANGE 1000
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_set_frequency(unsigned gpio, unsigned freq) {
    if (gpioSetPWMfrequency(gpio, freq) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%u, %u) failed\n", gpio, freq);
        return -1;
    }
    return 0;
}

static int safe_set_range(unsigned gpio, unsigned range) {
    if (gpioSetPWMrange(gpio, range) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%u, %u) failed\n", gpio, range);
        return -1;
    }
    return 0;
}

static int safe_pwm_write(unsigned gpio, unsigned duty) {
    if (gpioPWM(gpio, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM(%u, %u) failed\n", gpio, duty);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    unsigned pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (safe_set_mode(pins[i], PI_OUTPUT) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
        if (safe_set_frequency(pins[i], PWM_FREQ) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
        if (safe_set_range(pins[i], PWM_RANGE) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

    int duty = 0;
    while (running) {
        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
            if (safe_pwm_write(pins[i], duty) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
        }
        printf("PWM duty cycle: %d\n", duty);
        fflush(stdout);

        duty = (duty + 10) % (PWM_RANGE + 1);
        time_sleep(0.1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://mqtt.example.com:1883"
#define MQTT_TOPIC "sensor/data"
#define MQTT_CLIENT_ID "rpi_sensor"
#define MQTT_TIMEOUT 10000

#define SENSOR_PIN 4
#define SENSOR_VALID_MIN 0
#define SENSOR_VALID_MAX 1023

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < SENSOR_VALID_MIN || value > SENSOR_VALID_MAX) {
        fprintf(stderr, "Sensor reading out of range: %d\n", value);
        return -1;
    }
    return value;
}

int main(void) {
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    int rc;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID,
                          MQTTCLIENT_PERSISTENCE_NONE, NULL) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    conn_opts.connectTimeout = MQTT_TIMEOUT;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int sensor_value = read_sensor(SENSOR_PIN);
    if (sensor_value < 0) {
        fprintf(stderr, "Sensor reading failed; aborting.\n");
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    char payload[32];
    snprintf(payload, sizeof(payload), "%d", sensor_value);

    pubmsg.payload = payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    if ((rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
    } else {
        printf("Published sensor data: %s\n", payload);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    return (rc == MQTTCLIENT_SUCCESS) ? EXIT_SUCCESS : EXIT_FAILURE;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/ads1115"
#define ADS1115_ADDR 0x48
#define ADS1115_CONV_REG 0x00
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONFIG_BASE 0x8000
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_CONFIG_DEFAULT (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0_GND | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE)
#define I2C_BUS 1
#define NUM_READINGS 10

static volatile sig_atomic_t running = 1;
static struct mosquitto *mosq = NULL;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ads1115_write_config(int handle, uint16_t config) {
    char buf[3];
    buf[0] = ADS1115_CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (i2cWriteDevice(handle, buf, 3) < 0) {
        fprintf(stderr, "Error writing config to ADS1115\n");
        return -1;
    }
    return 0;
}

static int ads1115_read_conversion(int handle, int16_t *value) {
    char reg = ADS1115_CONV_REG;
    char buf[2];
    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        fprintf(stderr, "Error selecting conversion register\n");
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading conversion register\n");
        return -1;
    }
    *value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_ads1115(int handle, int16_t *value) {
    if (ads1115_write_config(handle, ADS1115_CONFIG_DEFAULT) < 0) return -1;
    gpioDelay(10000);
    if (ads1115_read_conversion(handle, value) < 0) return -1;
    return 0;
}

static void publish_reading(int16_t value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    char payload[64];
    snprintf(payload, sizeof(payload), "%s,%d", timestamp, value);
    if (mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message\n");
    }
}

static void cleanup(void) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating Mosquitto instance\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, (void (*)(struct mosquitto *, void *, int))NULL);
    mosquitto_disconnect_callback_set(mosq, (void (*)(struct mosquitto *, void *, int))NULL);
    mosquitto_reconnect_callback_set(mosq, (void (*)(struct mosquitto *, void *, int))NULL);

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    for (int i = 0; i < NUM_READINGS && running; i++) {
        int16_t value;
        if (read_ads1115(i2c_handle, &value) == 0) {
            publish_reading(value);
        } else {
            fprintf(stderr, "Error reading ADS1115\n");
        }
        gpioDelay(100000);
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_OUT_17 17
#define GPIO_OUT_18 18
#define CONSUMER "gpio-toggle"

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_OUT_17);
    if (!line17) {
        perror("gpiod_chip_get_line(17)");
        goto cleanup;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_OUT_18);
    if (!line18) {
        perror("gpiod_chip_get_line(18)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line17, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(17)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line18, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(18)");
        goto cleanup;
    }

    while (keep_running) {
        int v17 = gpiod_line_get_value(line17);
        int v18 = gpiod_line_get_value(line18);

        if (v17 < 0) {
            perror("gpiod_line_get_value(17)");
            goto cleanup;
        }
        if (v18 < 0) {
            perror("gpiod_line_get_value(18)");
            goto cleanup;
        }

        int new_v17 = !v17;
        int new_v18 = !v18;

        if (gpiod_line_set_value(line17, new_v17) < 0) {
            perror("gpiod_line_set_value(17)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line18, new_v18) < 0) {
            perror("gpiod_line_set_value(18)");
            goto cleanup;
        }

        printf("GPIO 17: %d, GPIO 18: %d\n", new_v17, new_v18);
        fflush(stdout);

        usleep(50000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (chip)   gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define CONSUMER "gpio-output"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO 17 output toggled every 5 seconds. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        val = !val;
        ret = gpiod_line_set_value(line, val);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO 17 set to %d\n", val);
        fflush(stdout);

        /* Sleep 5 seconds, but wake early if interrupted by signal */
        for (int i = 0; i < 5 && keep_running; i++) {
            sleep(1);
        }
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nGPIO released. Exiting.\n");
    return EXIT_SUCCESS;
}

