#define MQTT_BROKER_ADDRESS "tcp://mqtt.example.com:1883"
#define MQTT_TOPIC "sensor/data"
#define MQTT_CLIENT_ID "rpi_sensor_client"
#define MQTT_USERNAME "username"
#define MQTT_PASSWORD "password"
#define SENSOR_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_sensor_data(float *temperature, float *humidity) {
    /*
     * Replace with actual sensor reading logic.
     * This is a placeholder to demonstrate the structure.
     */
    *temperature = 25.0f + (rand() % 100) / 10.0f;
    *humidity = 50.0f + (rand() % 100) / 10.0f;
    return 0;
}

int main() {
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    int rc;
    float temperature, humidity;
    char payload[256];

    srand(time(NULL));

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID,
                      MQTTCLIENT_PERSISTENCE_NONE, NULL);

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    conn_opts.username = MQTT_USERNAME;
    conn_opts.password = MQTT_PASSWORD;

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    while (running) {
        if (read_sensor_data(&temperature, &humidity) != 0) {
            fprintf(stderr, "Error reading sensor data\n");
        } else {
            snprintf(payload, sizeof(payload), "{\"temperature\": %.2f, \"humidity\": %.2f}",
                     temperature, humidity);

            pubmsg.payload = payload;
            pubmsg.payloadlen = (int)strlen(payload);
            pubmsg.qos = 1;
            pubmsg.retained = 0;

            rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token);
            if (rc != MQTTCLIENT_SUCCESS) {
                fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
            }

            printf("Published: %s\n", payload);
        }

        sleep(SENSOR_INTERVAL_SEC);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_PINS 5
static const int pins[NUM_PINS] = {2, 3, 18, 23, 24};

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (device may be absent)\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    for (int duty = 0; duty <= 255 && running; duty++) {
        for (int i = 0; i < NUM_PINS; i++) {
            if (gpioPWM(pins[i], duty) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("Duty cycle: %3d\n", duty);
        fflush(stdout);
        gpioDelay(100000); /* 100 ms */
    }

    for (int i = 0; i < NUM_PINS; i++) {
        gpioPWM(pins[i], 0);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27
#define PWM_FREQ 1000
#define PWM_RANGE 255
#define STEP_DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned pin) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u) failed\n", pin);
        return -1;
    }
    return 0;
}

static int safe_set_pwm(unsigned pin, int duty) {
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM(%u, %d) failed\n", pin, duty);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(PWM_PIN_1) != 0 ||
        safe_set_mode(PWM_PIN_2) != 0 ||
        safe_set_mode(PWM_PIN_3) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) != PWM_FREQ ||
        gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) != PWM_FREQ ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != PWM_RANGE ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != PWM_RANGE ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    int duty = 0;
    while (running) {
        if (safe_set_pwm(PWM_PIN_1, duty) != 0 ||
            safe_set_pwm(PWM_PIN_2, duty) != 0 ||
            safe_set_pwm(PWM_PIN_3, duty) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
        printf("PWM on GPIO %d, %d, %d set to %d\n", PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, duty);
        fflush(stdout);

        duty = (duty + 1) % (PWM_RANGE + 1);

        if (duty == 0) {
            break;
        }
        usleep(STEP_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <sys/mman.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

static void errno_exit(const char *s) {
    fprintf(stderr, "%s error %d, %s\n", s, errno, strerror(errno));
    exit(EXIT_FAILURE);
}

int main(void) {
    const char *dev_name = "/dev/video0";
    int fd = -1;
    enum v4l2_buf_type type;
    struct v4l2_buffer buf;
    struct v4l2_format fmt;
    unsigned char *mem_start = NULL;
    unsigned int mem_size = 0;
    int ret;

    fd = open(dev_name, O_RDWR, 0);
    if (fd < 0) {
        fprintf(stderr, "Cannot open '%s': %s\n", dev_name, strerror(errno));
        return EXIT_FAILURE;
    }

    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &buf) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    buf.index = 0;
    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    mem_size = buf.length;
