            if (gpiod_line_set_value(lines[i], val) < 0) {
                fprintf(stderr, "Failed to set value on line %u\n", offsets[i]);
                goto cleanup;
            }
            printf("Set line %u to %d\n", offsets[i], val);
        }
        sleep(PERIOD_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "rpi/sensor"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static struct mosquitto *mosq = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void publish_reading(int value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char payload[64];
    snprintf(payload, sizeof(payload), "{\"timestamp\":\"%s\",\"value\":%d}", timestamp, value);

    if (mosquitto_publish(mosq, NULL, MQTT_TOPIC, (int)strlen(payload), payload, 0, false) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to publish message\n");
    } else {
        printf("Published: %s\n", payload);
    }
}

static void cleanup(void) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();

    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Mosquitto initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "MQTT connect failed: %s\n", mosquitto_strerror(rc));
        cleanup();
        return EXIT_FAILURE;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "MQTT loop start failed: %s\n", mosquitto_strerror(rc));
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        int value = read_mcp3008(ADC_CHANNEL);
        if (value >= 0) {
            publish_reading(value);
        } else {
            fprintf(stderr, "Failed to read ADC\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

int main(int argc, char *argv[]) {
    const char *dev_name = "/dev/video0";
    const char *out_name = "capture.jpg";

    if (argc > 1) dev_name = argv[1];
    if (argc > 2) out_name = argv[2];

    int fd = open(dev_name, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: cannot open %s: ", dev_name);
        perror("");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    CLEAR(cap);
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error: VIDIOC_QUERYCAP failed: ");
        perror("");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s does not support video capture\n", dev_name);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", dev_name);
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error: VIDIOC_S_FMT failed: ");
        perror("");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    CLEAR(req);
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error: VIDIOC_REQBUFS failed: ");
        perror("");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error: VIDIOC_QUERYBUF failed: ");
        perror("");
        close(fd);
        return EXIT_FAILURE;
    }

    void *mem = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (mem == MAP_FAILED) {
        fprintf(stderr, "Error: mmap failed: ");
        perror("");
        close(fd);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error: VIDIOC_QBUF failed: ");
        perror("");
        munmap(mem, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error: VIDIOC_STREAMON failed: ");
        perror("");
        munmap(mem, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error: VIDIOC_DQBUF failed: ");
        perror("");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(mem, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *out = fopen(out_name, "wb");
    if (!out) {
        fprintf(stderr, "Error: cannot open %s for writing: ", out_name);
        perror("");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(mem, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    size_t written = fwrite(mem, 1, buf.bytesused, out);
    if (written != (size_t)buf.bytesused) {
        fprintf(stderr, "Error: short write (%zu of %d bytes)\n", written, buf.bytesused);
        fclose(out);
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(mem, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    fclose(out);

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Warning: VIDIOC_STREAMOFF failed: ");
        perror("");
    }

    munmap(mem, buf.length);
    close(fd);

    printf("Image saved to %s (%d x %d, %d bytes)\n",
           out_name, fmt.fmt.pix.width, fmt.fmt.pix.height, buf.bytesused);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_PINS 6
static const int pins[NUM_PINS] = {4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    for (int duty = 0; duty <= 255 && running; duty++) {
        for (int i = 0; i < NUM_PINS; i++) {
            if (gpioPWM(pins[i], duty) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("Duty cycle: %3d\n", duty);
        fflush(stdout);
        gpioDelay(100000); /* 100 ms */
    }

    for (int i = 0; i < NUM_PINS; i++) {
        gpioPWM(pins[i], 0);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

