#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CHIP_NAME   "gpiochip0"
#define TIMEOUT_US  30000   /* 30 ms timeout for echo */

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Measure distance in centimetres.
 * Returns -1 on timeout or read error.
 */
static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo)
{
    struct timespec ts_start, ts_end;
    long elapsed_us;

    /* Ensure trigger is low before starting */
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(trig, 0)");
        return -1;
    }
    usleep(2);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value(trig, 1)");
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(trig, 0)");
        return -1;
    }

    /* Wait for echo rising edge (timeout) */
    int val;
    int waited = 0;
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value(echo)");
            return -1;
        }
        if (val == 1)
            break;
        usleep(1);
        waited++;
    } while (waited < TIMEOUT_US);

    if (val != 1) {
        fprintf(stderr, "Timeout waiting for echo rising edge\n");
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &ts_start);

    /* Wait for echo falling edge (timeout) */
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value(echo)");
            return -1;
        }
        if (val == 0)
            break;
        usleep(1);
        waited++;
    } while (waited < TIMEOUT_US);

    if (val != 0) {
        fprintf(stderr, "Timeout waiting for echo falling edge\n");
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &ts_end);

    elapsed_us = (ts_end.tv_sec - ts_start.tv_sec) * 1000000L +
                 (ts_end.tv_nsec - ts_start.tv_nsec) / 1000L;

    /* Speed of sound 343 m/s => 34300 cm/s => 0.0343 cm/us */
    return (int)(elapsed_us * 0.0343);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trig)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    while (running) {
        int dist = measure_distance(trig, echo);
        if (dist >= 0) {
            printf("Distance: %d cm\n", dist);
            fflush(stdout);
        } else {
            fprintf(stderr, "Measurement failed\n");
        }
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig)
        gpiod_line_release(trig);
    if (echo)
        gpiod_line_release(echo);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 11
#define PWM_PIN_4 18

#define PWM_RANGE 1000
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_set_frequency(unsigned gpio, unsigned freq) {
    if (gpioSetPWMfrequency(gpio, freq) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%u, %u) failed\n", gpio, freq);
        return -1;
    }
    return 0;
}

static int safe_set_range(unsigned gpio, unsigned range) {
    if (gpioSetPWMrange(gpio, range) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%u, %u) failed\n", gpio, range);
        return -1;
    }
    return 0;
}

static int safe_pwm_write(unsigned gpio, unsigned duty) {
    if (gpioPWM(gpio, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM(%u, %u) failed\n", gpio, duty);
        return -1;
    }
    return 0;
}

static int safe_pwm_stop(unsigned gpio) {
    if (gpioPWM(gpio, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM(%u, 0) failed\n", gpio);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    safe_pwm_stop(PWM_PIN_1);
    safe_pwm_stop(PWM_PIN_2);
    safe_pwm_stop(PWM_PIN_3);
    safe_pwm_stop(PWM_PIN_4);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    unsigned pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    const int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    for (int i = 0; i < num_pins; i++) {
        if (safe_set_mode(pins[i], PI_OUTPUT) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
        if (safe_set_frequency(pins[i], PWM_FREQ) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
        if (safe_set_range(pins[i], PWM_RANGE) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

    int duty = 0;
    while (running) {
        for (int i = 0; i < num_pins; i++) {
            if (safe_pwm_write(pins[i], duty) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
        }
        printf("PWM duty cycle: %d\n", duty);
        fflush(stdout);

        duty = (duty + 1) % (PWM_RANGE + 1);

        if (duty == 0) {
            break;
        }
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <sys/mman.h>

#define CAMERA_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 3)
#define FILENAME_LEN 64

static void cleanup(int fd, void *buffer, unsigned int length) {
    if (buffer && fd >= 0) {
        munmap(buffer, length);
        close(fd);
    }
}

int main(void) {
    int fd = -1;
    void *buffer = NULL;
    unsigned int length = 0;
    char filename[FILENAME_LEN];
    int ret;

    fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", CAMERA_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        cleanup(fd, buffer, length);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        cleanup(fd, buffer, length);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        cleanup(fd, buffer, length);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB24;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        cleanup(fd, buffer, length);
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        cleanup(fd, buffer, length);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        cleanup(fd, buffer, length);
        return EXIT_FAILURE;
    }

    length = buf.length;
    buffer = mmap(NULL, length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        buffer = NULL;
        cleanup(fd, buffer, length);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        cleanup(fd, buffer, length);
        return EXIT_FAILURE;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        cleanup(fd, buffer, length);
        return EXIT_FAILURE;
    }

    while (1) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
            break;
        }

        snprintf(filename, sizeof(filename), "image_%ld.jpg", (long)buf.timestamp.tv_sec);

        FILE *fp = fopen(filename, "wb");
        if (fp == NULL) {
            fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
            if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
                fprintf(stderr, "Error re-queuing buffer: %s\n", strerror(errno));
            }
            break;
        }

        if (fwrite(buffer, 1, buf.bytesused, fp) != buf.bytesused) {
            fprintf(stderr, "Error writing to file %s\n", filename);
            fclose(fp);
            if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
                fprintf(stderr, "Error re-queuing buffer: %s\n", strerror(errno));
            }
            break;
        }

        fclose(fp);
        printf("Image saved to %s\n", filename);

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error re-queuing buffer: %s\n", strerror(errno));
            break;
        }

        usleep(100000);
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
    }

    cleanup(fd, buffer, length);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 255
#define STEP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, sig_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGTERM, sig_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGTERM handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty = 0;
    int step = 1;

    while (running) {
        if (gpioPWM(PWM_PIN, duty) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", PWM_PIN);
            break;
        }

        printf("PWM duty cycle set to %d/%d\n", duty, PWM_RANGE);
        fflush(stdout);

        if (duty == 0 || duty == PWM_RANGE) {
            step = (duty == 0) ? 1 : -1;
        }
        duty += step;

        if (running) {
            gpioDelay(STEP_DELAY_US);
        }
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8574_ADDR   0x27
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t val)
{
    if (write(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                PCF8574_ADDR, strerror(errno));
        goto cleanup;
    }

    for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
        if (i2c_write_byte(fd, 0x00) == 0) {
            printf("PCF8574 initialized and cleared.\n");
            ret = EXIT_SUCCESS;
            goto cleanup;
        }
        if (attempt < MAX_RETRIES - 1)
            sleep(1);
    }

    fprintf(stderr, "PCF8574 initialization failed after %d attempts.\n", MAX_RETRIES);

cleanup:
    if (fd >= 0)
        close(fd);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 16

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Apply HIGH state */
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value (HIGH)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Report state */
    printf("GPIO %d set HIGH\n", GPIO_LINE);
    fflush(stdout);

    /* Wait for signal or 1 second */
    while (keep_running) {
        sleep(1);
    }

    /* Clean shutdown: set LOW and release */
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("GPIO %d set LOW and released\n", GPIO_LINE);
    fflush(stdout);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 27

static volatile sig_atomic_t keep_running = 1;

