#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SHT31_ADDR 0x44
#define I2C_BUS "/dev/i2c-1"
#define MEAS_CMD_HIGH 0x2C
#define MEAS_CMD_LOW 0x06
#define MEAS_DELAY_MS 15
#define LOOP_DELAY_S 5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t msb, uint8_t lsb) {
    uint8_t buf[2] = { msb, lsb };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sht31(int fd, float *temp, float *hum) {
    if (i2c_write_cmd(fd, MEAS_CMD_HIGH, MEAS_CMD_LOW) < 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    uint8_t data[6];
    if (i2c_read_bytes(fd, data, 6) < 0)
        return -1;

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temp = -45.0f + (175.0f * (float)t_raw / 65535.0f);
    *hum  = 100.0f * (float)h_raw / 65535.0f;

    if (*temp < -40.0f || *temp > 125.0f || *hum < 0.0f || *hum > 100.0f) {
        fprintf(stderr, "Reading out of range: T=%.2f H=%.2f\n", *temp, *hum);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", SHT31_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    printf("SHT31 sensor reading started (addr 0x%02X on %s). Press Ctrl+C to exit.\n",
           SHT31_ADDR, I2C_BUS);

    while (running) {
        float temp, hum;
        if (read_sht31(fd, &temp, &hum) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }
        sleep(LOOP_DELAY_S);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return 0;
}

