#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 27

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    for (int duty = 0; duty <= 255 && running; duty++) {
        for (int i = 0; i < num_pins; i++) {
            if (gpioPWM(pins[i], duty) != 0) {
                fprintf(stderr, "Error: failed to set PWM on GPIO %d.\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("Duty cycle: %3d\n", duty);
        fflush(stdout);
        gpioDelay(10000);
    }

    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_OUT_1 2
#define GPIO_OUT_2 3

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret;

    /* Install signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get lines */
    line1 = gpiod_chip_get_line(chip, GPIO_OUT_1);
    if (!line1) {
        perror("gpiod_chip_get_line (GPIO 2)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_OUT_2);
    if (!line2) {
        perror("gpiod_chip_get_line (GPIO 3)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initial value 0 */
    ret = gpiod_line_request_output(line1, "gpio-toggle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO 2)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line2, "gpio-toggle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO 3)");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: toggle once per second */
    while (keep_running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0) {
            perror("gpiod_line_get_value (GPIO 2)");
            break;
        }
        if (val2 < 0) {
            perror("gpiod_line_get_value (GPIO 3)");
            break;
        }

        int new_val1 = (val1 == 0) ? 1 : 0;
        int new_val2 = (val2 == 0) ? 1 : 0;

        ret = gpiod_line_set_value(line1, new_val1);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 2)");
            break;
        }
        ret = gpiod_line_set_value(line2, new_val2);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 3)");
            break;
        }

        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_OUT_1, new_val1, GPIO_OUT_2, new_val2);
        fflush(stdout);

        sleep(1);
    }

    /* Clean up: release lines and close chip */
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

