#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIN 18
#define NUM_LEDS 10
#define CYCLES 3
#define DELAY_US 50000  /* 0.005 s */

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_led(int pin, int r, int g, int b) {
    /*
     * pigpio's gpioPWM controls the duty cycle (0-255).
     * For a full-colour LED, we drive each channel independently.
     * For a strip of NUM_LEDS, we drive each channel once per LED.
     * We use a simple linear mapping: 0-255 -> 0-1000.
     */
    int pwm_r = (r * 1000) / 255;
    int pwm_g = (g * 1000) / 255;
    int pwm_b = (b * 1000) / 255;

    for (int i = 0; i < NUM_LEDS; i++) {
        gpioPWM(pin, pwm_r);
        gpioDelay(DELAY_US);
        gpioPWM(pin, pwm_g);
        gpioDelay(DELAY_US);
        gpioPWM(pin, pwm_b);
        gpioDelay(DELAY_US);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (device not ready?)\n");
        return EXIT_FAILURE;
    }

    /* Set pin as output and ensure it starts low */
    gpioSetMode(PIN, PI_OUTPUT);
    gpioWrite(PIN, 0);

    for (int cycle = 0; cycle < CYCLES && running; cycle++) {
        set_led(PIN, 255, 0, 0);   /* Red */
        set_led(PIN, 0, 255, 0);   /* Green */
        set_led(PIN, 0, 0, 255);   /* Blue */
    }

    /* Turn off the strip before exiting */
    gpioWrite(PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

