#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define W1_DEV_PATH "/sys/bus/w1/devices"
#define W1_SLAVE_FILE "w1_slave"
#define MAX_DEVICES 16
#define MAX_PATH 256

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int find_ds18b20(char *out, size_t out_len) {
    FILE *fp = popen("ls /sys/bus/w1/devices/ | grep '^28-'", "r");
    if (!fp) {
        fprintf(stderr, "popen failed: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    int found = 0;
    while (fgets(line, sizeof(line), fp)) {
        size_t len = strlen(line);
        while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) {
            line[--len] = '\0';
        }
        if (len > 0) {
            snprintf(out, out_len, "%s/%s/%s", W1_DEV_PATH, line, W1_SLAVE_FILE);
            found = 1;
            break;
        }
    }
    pclose(fp);
    return found ? 0 : -1;
}

static int read_temperature(const char *dev_path, float *temp_c) {
    FILE *fp = fopen(dev_path, "r");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", dev_path, strerror(errno));
        return -1;
    }

    char line[256];
    int crc_ok = 0;
    float raw = -273.15f;

    while (fgets(line, sizeof(line), fp)) {
        if (strstr(line, "crc=")) {
            crc_ok = 1;
        } else if (strstr(line, "t=")) {
            long val;
            if (sscanf(line, "t=%ld", &val) == 1) {
                raw = (float)val / 1000.0f;
            }
        }
    }
    fclose(fp);

    if (!crc_ok) {
        fprintf(stderr, "CRC check failed for %s\n", dev_path);
        return -1;
    }
    if (raw <= -273.0f) {
        fprintf(stderr, "Temperature read failed for %s\n", dev_path);
        return -1;
    }

    *temp_c = raw;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    char dev_path[MAX_PATH];
    if (find_ds18b20(dev_path, sizeof(dev_path)) != 0) {
        fprintf(stderr, "No DS18B20 device found on 1-Wire bus.\n");
        return 1;
    }

    printf("DS18B20 found at %s\n", dev_path);

    for (int i = 0; i < 3 && g_running; i++) {
        float temp;
        if (read_temperature(dev_path, &temp) == 0) {
            printf("Temperature: %.2f C\n", temp);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
            return 1;
        }
        if (i < 2 && g_running) {
            sleep(5);
        }
    }

    printf("Program finished.\n");
    return 0;
}

