#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define LED_PIN 24

#define SPEED_OF_SOUND 34300.0
#define TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {
        .tv_sec = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

static void sleep_ms(unsigned int ms) {
    sleep_us(ms * 1000U);
}

static void trigger_sensor(struct gpiod_line *trig) {
    gpiod_line_set_value(trig, 1);
    sleep_us(10);
    gpiod_line_set_value(trig, 0);
}

static long long measure_pulse(struct gpiod_line *echo) {
    long long start = now_us();
    while (gpiod_line_get_value(echo) == 0) {
        if (now_us() - start > TIMEOUT_US) return -1;
    }
    long long rise = now_us();
    while (gpiod_line_get_value(echo) == 1) {
        if (now_us() - rise > TIMEOUT_US) return -1;
    }
    long long fall = now_us();
    return fall - rise;
}

static double calculate_distance(long long pulse_us) {
    if (pulse_us < 0) return -1.0;
    return (double)pulse_us * SPEED_OF_SOUND / 2000000.0;
}

int main(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!trig || !echo || !led) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("request_output trig");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("request_input echo");
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "hc-sr04-led", 0) < 0) {
        perror("request_output led");
        goto cleanup;
    }

    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_sensor(trig);
        long long pulse = measure_pulse(echo);
        double dist = calculate_distance(pulse);

        if (dist < 0) {
            printf("Sensor timeout or error.\n");
            gpiod_line_set_value(led, 0);
        } else {
            printf("Distance: %.2f cm\n", dist);
            if (dist < 20.0) {
                gpiod_line_set_value(led, 1);
            } else {
                gpiod_line_set_value(led, 0);
            }
        }
        sleep_ms(100);
    }

cleanup:
    gpiod_line_set_value(led, 0);
    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

