        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value 1 */
    ret = gpiod_line_request_output(line, "gpio-27-output", 1);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Apply the output state */
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Report the state */
    printf("GPIO %d set to HIGH\n", GPIO_LINE_OFFSET);
    fflush(stdout);

    /* Clean up */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE 8
#define NUM_CYCLES 3

static volatile sig_atomic_t keep_running = 1;

static void handle_sig(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_sig;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "gpio-control", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Apply the output for the specified number of cycles */
    for (int i = 0; i < NUM_CYCLES && keep_running; i++) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (HIGH)");
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_LINE);
        fflush(stdout);
        sleep(1);

        if (!keep_running) break;

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (LOW)");
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_LINE);
        fflush(stdout);
        sleep(1);
    }

    /* Clean up: set line LOW and release resources */
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

