#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 17
#define PWM_PIN_3 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define SLEEP_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm_value(int pin, int value) {
    if (value < 0 || value > PWM_RANGE) {
        fprintf(stderr, "Error: Invalid PWM value %d for pin %d (must be 0-%d)\n",
                value, pin, PWM_RANGE);
        return -1;
    }
    if (gpioPWM(pin, value) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int read_pwm_value(int pin) {
    int value = gpioGetPWMdutycycle(pin);
    if (value < 0) {
        fprintf(stderr, "Error: gpioGetPWMdutycycle failed on pin %d\n", pin);
        return -1;
    }
    return value;
}

static void cleanup(void) {
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Cannot install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pwm_value = 0;
    while (running) {
        if (set_pwm_value(PWM_PIN_1, pwm_value) != 0 ||
            set_pwm_value(PWM_PIN_2, pwm_value) != 0 ||
            set_pwm_value(PWM_PIN_3, pwm_value) != 0) {
            fprintf(stderr, "Error: Failed to set PWM values\n");
            break;
        }

        int v1 = read_pwm_value(PWM_PIN_1);
        int v2 = read_pwm_value(PWM_PIN_2);
        int v3 = read_pwm_value(PWM_PIN_3);

        if (v1 < 0 || v2 < 0 || v3 < 0) {
            fprintf(stderr, "Error: Failed to read PWM values\n");
            break;
        }

        printf("PWM_PIN_1: %d, PWM_PIN_2: %d, PWM_PIN_3: %d\n", v1, v2, v3);
        fflush(stdout);

        pwm_value = (pwm_value + 1) % (PWM_RANGE + 1);

        if (pwm_value == 0) {
            break;
        }

        usleep(SLEEP_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

