#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define MAX_TIMINGS 85

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {
        .tv_sec = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    int data[5] = {0, 0, 0, 0, 0};
    int last = -1;
    int counter = 0;

    if (gpiod_line_request_output(line, "dht22", 1) < 0) {
        perror("gpiod_line_request_output");
        return -1;
    }
    gpiod_line_set_value(line, 1);
    sleep_us(500);
    gpiod_line_set_value(line, 0);
    sleep_us(20000);
    gpiod_line_set_value(line, 1);
    sleep_us(30);

    if (gpiod_line_request_input(line, "dht22") < 0) {
        perror("gpiod_line_request_input");
        return -1;
    }

    for (int i = 0; i < MAX_TIMINGS; i++) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            return -1;
        }
        if (val != last) {
            last = val;
            counter++;
        }
    }

    if (counter < 30) {
        fprintf(stderr, "DHT22: No response (counter=%d)\n", counter);
        return -1;
    }

    for (int i = 0; i < 40; i++) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            return -1;
        }
        data[i / 8] <<= 1;
        if (val) data[i / 8] |= 1;
        counter = 0;
        while (gpiod_line_get_value(line) == val) {
            counter++;
            if (counter > 100) break;
        }
        if (counter > 100) {
            fprintf(stderr, "DHT22: Timeout at bit %d\n", i);
            return -1;
        }
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "DHT22: Checksum error\n");
        return -1;
    }

    *hum = (float)((data[0] << 8) + data[1]) / 10.0f;
    *temp = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0f;
    if (data[2] & 0x80) *temp = -*temp;

    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3 && running; i++) {
        float temp, hum;
        if (read_dht22(line, &temp, &hum) == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp, hum);
        } else {
            fprintf(stderr, "DHT22 read failed on cycle %d\n", i + 1);
        }
        if (i < 2 && running) sleep(2);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

