    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN2, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN2, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty = 0;
    int step = 1;

    while (running) {
        if (gpioPWM(PWM_PIN, duty) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN);
            break;
        }
        if (gpioPWM(PWM_PIN2, duty) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN2);
            break;
        }

        printf("PWM on GPIO %d and GPIO %d set to %d\n", PWM_PIN, PWM_PIN2, duty);
        fflush(stdout);

        duty += step;
        if (duty >= PWM_RANGE) {
            duty = PWM_RANGE;
            step = -1;
        } else if (duty <= 0) {
            duty = 0;
            step = 1;
        }

        gpioDelay(100000);
    }

    gpioPWM(PWM_PIN, 0);
    gpioPWM(PWM_PIN2, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

