#include <gpiod.h>

#define GPIO_17 17
#define GPIO_18 18
#define GPIO_23 23

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL, *line18 = NULL, *line23 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    line23 = gpiod_chip_get_line(chip, GPIO_23);
    if (!line17 || !line18 || !line23) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request each line as output, initial value LOW */
    ret = gpiod_line_request_output(line17, "gpio-control", 0);
    if (ret < 0) { perror("gpiod_line_request_output 17"); goto cleanup; }
    ret = gpiod_line_request_output(line18, "gpio-control", 0);
    if (ret < 0) { perror("gpiod_line_request_output 18"); goto cleanup; }
    ret = gpiod_line_request_output(line23, "gpio-control", 0);
    if (ret < 0) { perror("gpiod_line_request_output 23"); goto cleanup; }

    /* Apply HIGH to GPIO 17, LOW to GPIO 18, HIGH to GPIO 23 */
    ret = gpiod_line_set_value(line17, 1);
    if (ret < 0) { perror("gpiod_line_set_value 17"); goto cleanup; }
    ret = gpiod_line_set_value(line18, 0);
    if (ret < 0) { perror("gpiod_line_set_value 18"); goto cleanup; }
    ret = gpiod_line_set_value(line23, 1);
    if (ret < 0) { perror("gpiod_line_set_value 23"); goto cleanup; }

    printf("GPIO 17=HIGH, GPIO 18=LOW, GPIO 23=HIGH\n");
    fflush(stdout);

    /* Hold for a short interval (1 second) */
    while (running) {
        sleep(1);
    }

    /* Clean shutdown: return lines to LOW */
    gpiod_line_set_value(line17, 0);
    gpiod_line_set_value(line18, 0);
    gpiod_line_set_value(line23, 0);

cleanup:
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (line23) gpiod_line_release(line23);
