#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 17
#define PWM_PIN_3 18
#define PWM_PIN_4 27

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define PWM_DUTY_CYCLE 128
#define CYCLES_PER_CYCLE 5
#define CYCLE_DURATION_SEC 60

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

void cleanup_pwm(void) {
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set up signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    int num_pins = sizeof(pins) / sizeof(pins[0]);

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            cleanup_pwm();
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) != 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pins[i]);
            cleanup_pwm();
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pins[i]);
            cleanup_pwm();
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    int cycle_count = 0;
    while (program_running && cycle_count < CYCLES_PER_CYCLE) {
        for (int i = 0; i < num_pins; i++) {
            if (gpioPWM(pins[i], PWM_DUTY_CYCLE) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                cleanup_pwm();
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("Cycle %d/%d applied to GPIO %d, %d, %d, %d\n",
               cycle_count + 1, CYCLES_PER_CYCLE, PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4);
        fflush(stdout);
        cycle_count++;

        if (program_running && cycle_count < CYCLES_PER_CYCLE) {
            sleep(CYCLE_DURATION_SEC);
        }
    }

    cleanup_pwm();
    gpioTerminate();
    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

