#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_PINS 6
static const int pins[NUM_PINS] = {17, 18, 22, 23, 24, 25};

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

static int safe_set_mode(int pin, unsigned mode) {
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_set_pwm(int pin, int duty) {
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed\n", pin, duty);
        return -1;
    }
    return 0;
}

static int safe_write(int pin, int level) {
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed\n", pin, level);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (safe_set_mode(pins[i], PI_OUTPUT) < 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    int duty = 0;
    int step = 10;

    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            if (safe_set_pwm(pins[i], duty) < 0) goto cleanup;
        }
        printf("PWM duty: %d\n", duty);
        fflush(stdout);

        if (duty == 0 || duty == 255) step = -step;
        duty += step;
        if (duty < 0) duty = 0;
        if (duty > 255) duty = 255;

        time_sleep(0.05);
    }

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        safe_write(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

