    line23 = gpiod_chip_get_line(chip, GPIO_23);
    line24 = gpiod_chip_get_line(chip, GPIO_24);
    if (!line17 || !line23 || !line24) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request each line as output, initial value LOW */
    ret = gpiod_line_request_output(line17, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output line17");
        goto cleanup;
    }
    ret = gpiod_line_request_output(line23, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output line23");
        goto cleanup;
    }
    ret = gpiod_line_request_output(line24, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output line24");
        goto cleanup;
    }

    /* Main loop: apply each line HIGH once, then LOW once, then repeat */
    while (keep_running) {
        /* Apply HIGH to GPIO 17 */
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value line17 HIGH");
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_17);
        fflush(stdout);
        sleep(1);

        if (!keep_running) break;

        /* Apply LOW to GPIO 17 */
        ret = gpiod_line_set_value(line17, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value line17 LOW");
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_17);
        fflush(stdout);
        sleep(1);

        if (!keep_running) break;

        /* Apply HIGH to GPIO 23 */
        ret = gpiod_line_set_value(line23, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value line23 HIGH");
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_23);
        fflush(stdout);
        sleep(1);

        if (!keep_running) break;

        /* Apply LOW to GPIO 23 */
        ret = gpiod_line_set_value(line23, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value line23 LOW");
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_23);
        fflush(stdout);
        sleep(1);

        if (!keep_running) break;

        /* Apply HIGH to GPIO 24 */
        ret = gpiod_line_set_value(line24, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value line24 HIGH");
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_24);
        fflush(stdout);
        sleep(1);

        if (!keep_running) break;

        /* Apply LOW to GPIO 24 */
        ret = gpiod_line_set_value(line24, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value line24 LOW");
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_24);
        fflush(stdout);
        sleep(1);
    }

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line17) gpiod_line_release(line17);
    if (line23) gpiod_line_release(line23);
    if (line24) gpiod_line_release(line24);
    if (chip) gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define NUM_CYCLES 3
#define CYCLE_INTERVAL 60

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static void sleep_us(unsigned int us) {
    struct timespec ts = { 0, (long)us * 1000L };
    nanosleep(&ts, NULL);
}

static int wait_for_level(struct gpiod_line *line, int target, unsigned int timeout_us) {
    unsigned int elapsed = 0;
    while (gpiod_line_get_value(line) != target) {
        if (elapsed >= timeout_us) return -1;
        sleep_us(1);
        elapsed++;
    }
    return 0;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0, 0, 0, 0, 0};
    int last = -1;
    int counter = 0;

    if (gpiod_line_request_output(line, "dht22", 1) < 0) return -1;
    sleep_ms(1);
    gpiod_line_set_value(line, 0);
    sleep_ms(18);
    gpiod_line_set_value(line, 1);

    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    for (int i = 0; i < 85; i++) {
        counter = 0;
        while (gpiod_line_get_value(line) == last) {
            counter++;
            sleep_us(1);
            if (counter == 255) return -1;
        }
        last = gpiod_line_get_value(line);
        if ((i >= 4) && (i % 2 == 0)) {
            data[(i / 16)] |= (last << (7 - ((i / 2) % 8)));
        }
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return -1;
    }

    *hum = (float)((data[0] << 8) + data[1]) / 10.0f;
    *temp = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0f;
    if (data[2] & 0x80) *temp = -*temp;

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temp, hum;
    int ret = EXIT_FAILURE;

    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    for (int i = 0; i < NUM_CYCLES && running; i++) {
        if (read_dht22(line, &temp, &hum) == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp, hum);
            fflush(stdout);
        } else {
            fprintf(stderr, "DHT22 read failed on cycle %d\n", i + 1);
        }
        if (i < NUM_CYCLES - 1 && running) {
            for (int s = 0; s < CYCLE_INTERVAL && running; s++) {
                sleep_ms(1000);
            }
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

