#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 27
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned pin) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %u\n", pin);
        return -1;
    }
    return 0;
}

static int safe_set_frequency(unsigned pin, unsigned freq) {
    if (gpioSetPWMfrequency(pin, freq) != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for pin %u\n", pin);
        return -1;
    }
    return 0;
}

static int safe_set_range(unsigned pin, unsigned range) {
    if (gpioSetPWMrange(pin, range) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for pin %u\n", pin);
        return -1;
    }
    return 0;
}

static int safe_pwm_write(unsigned pin, unsigned duty) {
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM failed for pin %u\n", pin);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(PWM_PIN_1) != 0 ||
        safe_set_mode(PWM_PIN_2) != 0 ||
        safe_set_mode(PWM_PIN_3) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_frequency(PWM_PIN_1, PWM_FREQUENCY) != 0 ||
        safe_set_frequency(PWM_PIN_2, PWM_FREQUENCY) != 0 ||
        safe_set_frequency(PWM_PIN_3, PWM_FREQUENCY) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_range(PWM_PIN_1, PWM_RANGE) != 0 ||
        safe_set_range(PWM_PIN_2, PWM_RANGE) != 0 ||
        safe_set_range(PWM_PIN_3, PWM_RANGE) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty = 0;
    while (running) {
        if (safe_pwm_write(PWM_PIN_1, duty) != 0 ||
            safe_pwm_write(PWM_PIN_2, duty) != 0 ||
            safe_pwm_write(PWM_PIN_3, duty) != 0) {
            break;
        }
        printf("PWM duty cycle: %d\n", duty);
        fflush(stdout);
        duty = (duty + 1) % (PWM_RANGE + 1);
        sleep(1);
    }

    /* Ensure PWM is off before terminating */
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

