        }
        if (gpiod_line_set_value(line20, val20 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value(20)");
            goto cleanup;
        }

        usleep(100000); /* 0.1 seconds */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line16) gpiod_line_release(line16);
    if (line20) gpiod_line_release(line20);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_BITS_PER_WORD 8
#define SPI_MODE 0

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int spi_init(int *fd_out) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting max speed hz: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    *fd_out = fd;
    return 0;
}

static int read_max31855(int fd, float *temp_c, float *internal_c) {
    uint8_t rx[4] = {0};
    uint8_t tx[4] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 4,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    uint32_t raw = ((uint32_t)rx[0] << 24) |
                   ((uint32_t)rx[1] << 16) |
                   ((uint32_t)rx[2] << 8)  |
                   ((uint32_t)rx[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault detected (bit 16 set)\n");
        return -1;
    }

    int16_t therm_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (therm_raw & 0x2000) {
        therm_raw |= 0xC000;
    }
    *temp_c = therm_raw * 0.25f;

    int16_t int_raw = (int16_t)((raw >> 4) & 0x0FFF);
    if (int_raw & 0x0800) {
        int_raw |= 0xF000;
    }
    *internal_c = int_raw * 0.0625f;

    return 0;
}

int main(void) {
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    int fd = -1;
    if (spi_init(&fd) != 0) {
        return EXIT_FAILURE;
    }

    float temp_c = 0.0f;
    float internal_c = 0.0f;

    if (read_max31855(fd, &temp_c, &internal_c) == 0) {
        printf("Temperature: %.2f C, Internal: %.2f C\n", temp_c, internal_c);
    } else {
        fprintf(stderr, "Failed to read MAX31855\n");
    }

    if (fd >= 0) {
        close(fd);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_OUT_1 17
#define GPIO_OUT_2 18

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret;

    /* Install signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get lines */
    line1 = gpiod_chip_get_line(chip, GPIO_OUT_1);
    if (!line1) {
        perror("gpiod_chip_get_line (17)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_OUT_2);
    if (!line2) {
        perror("gpiod_chip_get_line (18)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initial value 0 */
    ret = gpiod_line_request_output(line1, "gpio-toggle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (17)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line2, "gpio-toggle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (18)");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: toggle both lines every 0.1 s */
    while (keep_running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0) {
            perror("gpiod_line_get_value (17)");
            break;
        }
        if (val2 < 0) {
            perror("gpiod_line_get_value (18)");
            break;
        }

        int new_val1 = (val1 == 0) ? 1 : 0;
        int new_val2 = (val2 == 0) ? 1 : 0;

        ret = gpiod_line_set_value(line1, new_val1);
        if (ret < 0) {
            perror("gpiod_line_set_value (17)");
            break;
        }
        ret = gpiod_line_set_value(line2, new_val2);
        if (ret < 0) {
            perror("gpiod_line_set_value (18)");
            break;
        }

        printf("GPIO 17: %d, GPIO 18: %d\n", new_val1, new_val2);
        fflush(stdout);

        usleep(100000); /* 0.1 s */
    }

    /* Clean up: set both lines low, release, close chip */
    gpiod_line_set_value(line1, 0);
    gpiod_line_set_value(line2, 0);
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define LED_PIN 18
#define BUZZER_PIN 27

#define TIMEOUT_US 30000
#define SPEED_OF_SOUND 34300.0

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long elapsed_us(struct timespec *start, struct timespec *end) {
    return (long long)(end->tv_sec - start->tv_sec) * 1000000LL +
           (end->tv_nsec - start->tv_nsec) / 1000LL;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL, *echo = NULL, *led = NULL, *buzzer = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    led = gpiod_chip_get_line(chip, LED_PIN);
    buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!trigger || !echo || !led || !buzzer) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hc-sr04", 0) < 0) {
        perror("gpiod_line_request_output (trigger)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "hc-sr04", 0) < 0) {
        perror("gpiod_line_request_output (led)");
        goto cleanup;
    }
    if (gpiod_line_request_output(buzzer, "hc-sr04", 0) < 0) {
        perror("gpiod_line_request_output (buzzer)");
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);

        if (gpiod_line_set_value(trigger, 1) < 0) {
            perror("gpiod_line_set_value (trigger high)");
            goto cleanup;
        }
        usleep(10);
        if (gpiod_line_set_value(trigger, 0) < 0) {
            perror("gpiod_line_set_value (trigger low)");
            goto cleanup;
        }

        struct timespec t_start, t_end;
        int val;
        int timeout = 0;

        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value (echo)");
                goto cleanup;
            }
            if (val == 1) break;
            usleep(10);
            clock_gettime(CLOCK_MONOTONIC, &t_start);
            timeout = 0;
        } while (running && elapsed_us(&t_start, &ts) < TIMEOUT_US);

        if (!running) break;
        if (timeout) {
            fprintf(stderr, "Timeout waiting for echo start.\n");
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC, &t_start);
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value (echo)");
                goto cleanup;
            }
            if (val == 0) break;
            usleep(10);
            clock_gettime(CLOCK_MONOTONIC, &t_end);
            timeout = 0;
        } while (running && elapsed_us(&t_start, &t_end) < TIMEOUT_US);

        if (!running) break;
        if (timeout) {
            fprintf(stderr, "Timeout waiting for echo end.\n");
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC, &t_end);
        long long elapsed = elapsed_us(&t_start, &t_end);
        double distance = (elapsed / 1000000.0) * SPEED_OF_SOUND / 2.0;

        printf("Distance: %.2f cm\n", distance);

        if (distance < 20.0) {
            if (gpiod_line_set_value(led, 1) < 0) {
                perror("gpiod_line_set_value (led on)");
                goto cleanup;
            }
            if (gpiod_line_set_value(buzzer, 1) < 0) {
                perror("gpiod_line_set_value (buzzer on)");
                goto cleanup;
            }
            usleep(500000);
            if (gpiod_line_set_value(led, 0) < 0) {
                perror("gpiod_line_set_value (led off)");
                goto cleanup;
            }
            if (gpiod_line_set_value(buzzer, 0) < 0) {
                perror("gpiod_line_set_value (buzzer off)");
                goto cleanup;
            }
        }

        usleep(50000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (led) gpiod_line_release(led);
    if (buzzer) gpiod_line_release(buzzer);
    if (chip) gpiod_chip_close(chip);

    printf("Exiting.\n");
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 18
#define CONSUMER "gpio-digital-output"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

