#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_ADDR 0x03
#define I2C_DEV "/dev/i2c-1"

#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA

#define BMP280_CHIP_ID 0x58

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, BMP280_REG_ID, &id) < 0) {
        fprintf(stderr, "Error: Failed to read chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X)\n", id, BMP280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg8(fd, BMP280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error: Failed to reset BMP280: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);

    if (i2c_write_reg8(fd, BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write config register: %s\n", strerror(errno));
        return -1;
    }

    if (i2c_write_reg8(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to write ctrl_meas register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int bmp280_read_raw(int fd, int32_t *temp, int32_t *press) {
    uint8_t data[6];
    if (i2c_read_block(fd, BMP280_REG_PRESS_MSB, data, 6) < 0) {
        fprintf(stderr, "Error: Failed to read sensor data: %s\n", strerror(errno));
        return -1;
    }

    *press = (int32_t)((data[0] << 12) | (data[1] << 4) | (data[2] >> 4));
    *temp = (int32_t)((data[3] << 12) | (data[4] << 4) | (data[5] >> 4));
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X: %s\n", BMP280_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (bmp280_init(fd) < 0) {
        fprintf(stderr, "Error: BMP280 initialization failed.\n");
        close(fd);
        return 1;
    }

    printf("BMP280 initialized successfully.\n");

    for (int i = 0; i < 3 && running; i++) {
        int32_t raw_temp, raw_press;
        if (bmp280_read_raw(fd, &raw_temp, &raw_press) == 0) {
            printf("Reading %d: Temp = %d, Press = %d\n", i + 1, raw_temp, raw_press);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }
        usleep(100000);
    }

    close(fd);
    printf("Program finished.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_PINS 4
static const unsigned int pins[NUM_PINS] = {17, 22, 23, 24};

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_PINS; i++) lines[i] = NULL;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %u\n", pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "gpio-control", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %u\n", pins[i]);
            goto cleanup;
        }
    }

    printf("GPIO pins initialized. Applying states...\n");
    fflush(stdout);

    for (int i = 0; i < NUM_PINS && running; i++) {
        int val = (i % 2 == 0) ? 1 : 0;
        if (gpiod_line_set_value(lines[i], val) < 0) {
            fprintf(stderr, "gpiod_line_set_value failed for pin %u\n", pins[i]);
            goto cleanup;
        }
        printf("Pin %u set to %d\n", pins[i], val);
        fflush(stdout);
        usleep(500000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) gpiod_chip_close(chip);
    return ret;
}

