#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BME280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"

#define BME280_REG_ID 0xD0
#define BME280_REG_RESET 0xE0
#define BME2C0_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_PRESS_MSB 0xF7
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_HUM_MSB 0xFD

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int bme280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg(fd, BME280_REG_ID, &id) < 0) {
        fprintf(stderr, "Error: Cannot read chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != 0x60) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x60)\n", id);
        return -1;
    }
    if (i2c_write_reg(fd, BME280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error: Cannot reset BME280: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);
    uint8_t status;
    int timeout = 100;
    do {
        if (i2c_read_reg(fd, BME280_REG_STATUS, &status) < 0) {
            fprintf(stderr, "Error: Cannot read status: %s\n", strerror(errno));
            return -1;
        }
        if (status & 0x01) {
            fprintf(stderr, "Error: Busy after reset\n");
            return -1;
        }
        usleep(2000);
    } while (--timeout && (status & 0x01));
    if (timeout == 0) {
        fprintf(stderr, "Error: Timeout waiting for BME280\n");
        return -1;
    }
    if (i2c_write_reg(fd, BME280_REG_CTRL_HUM, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, BME280_REG_CONFIG, 0xA0) < 0) return -1;
    if (i2c_write_reg(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    return 0;
}

static int bme280_read(int fd, float *temp, float *press, float *hum) {
    uint8_t data[8];
    if (i2c_read_burst(fd, BME280_REG_PRESS_MSB, data, 8) < 0) {
        fprintf(stderr, "Error: Cannot read sensor data: %s\n", strerror(errno));
        return -1;
    }
    int32_t raw_p = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_t = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int32_t raw_h = (data[6] << 8) | data[7];
    *temp = (float)raw_t / 100.0f;
    *press = (float)raw_p / 100.0f;
    *hum = (float)raw_h / 1024.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error: Cannot set I2C slave 0x%02X: %s\n", BME280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }
    if (bme280_init(fd) < 0) {
        fprintf(stderr, "Error: BME280 initialization failed\n");
        close(fd);
        return 1;
    }
    for (int i = 0; i < 3 && running; i++) {
        float temp, press, hum;
        if (bme280_read(fd, &temp, &press, &hum) == 0) {
            printf("Temperature: %.2f C, Pressure: %.2f hPa, Humidity: %.2f %%\n", temp, press, hum);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }
        if (i < 2 && running) sleep(5);
    }
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define CONSUMER "gpio-17-toggle"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: toggle once per second, exit on signal */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        int new_val = val ? 0 : 1;
        ret = gpiod_line_set_value(line, new_val);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE_OFFSET, new_val);
        fflush(stdout);

        /* Sleep 1 second, but wake early if a signal arrives */
        for (int i = 0; i < 10 && keep_running; i++) {
            usleep(100000); /* 100 ms */
        }
    }

    /* Clean up: release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define VEML7700_ADDR 0x10
#define I2C_DEVICE "/dev/i2c-1"

#define VEML7700_REG_CONFIG 0x00
#define VEML7700_REG_ALS_DATA 0x04

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Configure VEML7700: enable ALS, 1x gain, 100ms integration */
    if (i2c_write_reg8(fd, VEML7700_REG_CONFIG, 0x00) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t als_data;
        if (i2c_read_reg16(fd, VEML7700_REG_ALS_DATA, &als_data) < 0) {
            close(fd);
            return EXIT_FAILURE;
        }
        printf("ALS Data: %u\n", als_data);
        fflush(stdout);
        usleep(500000);
    }

    close(fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE B115200
#define READ_INTERVAL_US 100000  /* 0.1 seconds */
#define MAX_READ_LEN 256

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int setup_serial(const char *port, speed_t baud) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", port, strerror(errno));
        return -1;
    }

    /* Clear O_NDELAY so reads block */
    if (fcntl(fd, F_SETFL, 0) < 0) {
        fprintf(stderr, "Error clearing O_NDELAY: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag &= ~PARENB;   /* No parity */
    tty.c_cflag &= ~CSTOPB;   /* 1 stop bit */
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;       /* 8 data bits */
    tty.c_cflag &= ~CRTSCTS;  /* No hardware flow control */
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); /* No software flow control */
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG); /* Raw input */

    tty.c_oflag &= ~OPOST;  /* Raw output */

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 10;   /* 1 second inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }

    int fd = setup_serial(SERIAL_PORT, BAUD_RATE);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    printf("Serial port %s initialized at 115200 baud.\n", SERIAL_PORT);
    printf("Reading data from the device. Press Ctrl+C to exit.\n");

    char buffer[MAX_READ_LEN];
    int  bytes_read;

    while (g_running) {
        bytes_read = read(fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s", buffer);
            fflush(stdout);
        } else if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                /* No data available right now */
            } else {
                fprintf(stderr, "Error reading from serial port: %s\n", strerror(errno));
                break;
            }
        }
        /* bytes_read == 0: no data available, just loop */

        usleep(READ_INTERVAL_US);
    }

    printf("\nExiting program.\n");
    if (close(fd) != 0) {
        fprintf(stderr, "Warning: error closing serial port: %s\n", strerror(errno));
    }
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CHIP_NAME   "gpiochip0"
#define TIMEOUT_US  30000   /* 30 ms timeout for echo */
#define LOOP_DELAY_S 0.5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Measure distance in cm.
 * Returns 0 on success, -1 on timeout, -2 on read error.
 */
static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo)
{
    struct timespec ts_start, ts_end;
    long elapsed_us;

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(trig, 0)");
        return -2;
    }
    usleep(2);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value(trig, 1)");
        return -2;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(trig, 0)");
        return -2;
    }

    /* Wait for echo rising edge (timeout) */
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    while (gpiod_line_get_value(echo) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &ts_end);
        elapsed_us = (ts_end.tv_sec - ts_start.tv_sec) * 1000000L +
                     (ts_end.tv_nsec - ts_start.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            return -1;
        }
    }

    /* Record rising edge */
    clock_gettime(CLOCK_MONOTONIC, &ts_start);

    /* Wait for echo falling edge (timeout) */
    while (gpiod_line_get_value(echo) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &ts_end);
        elapsed_us = (ts_end.tv_sec - ts_start.tv_sec) * 1000000L +
                     (ts_end.tv_nsec - ts_start.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            return -1;
        }
    }

    /* Record falling edge */
    clock_gettime(CLOCK_MONOTONIC, &ts_end);

    elapsed_us = (ts_end.tv_sec - ts_start.tv_sec) * 1000000L +
                 (ts_end.tv_nsec - ts_start.tv_nsec) / 1000L;

    /* Speed of sound: 343 m/s = 0.0343 cm/us */
    int distance = (int)(elapsed_us * 0.0343f / 2.0f);

    /* Sanity check: HC-SR04 range 2 cm to 400 cm */
    if (distance < 2 || distance > 400) {
        return -1;
    }

    return distance;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get trigger line */
    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trig)");
        goto cleanup;
    }

    /* Get echo line */
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    /* Request trigger as output, initial value low */
    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }

    /* Request echo as input */
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = measure_distance(trig, echo);

        if (distance < 0) {
            if (distance == -1) {
                fprintf(stderr, "Warning: Echo timeout (sensor not responding or out of range)\n");
            } else {
                fprintf(stderr, "Warning: Invalid distance reading\n");
            }
        } else {
            printf("Distance: %d cm\n", distance);
        }

        /* Sleep 0.5 seconds, but wake early if interrupted */
        for (int i = 0; i < 50 && running; i++) {
            usleep(10000); /* 10 ms */
        }
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

