    /* Request line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "gpio-8-toggle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: toggle once every 0.001 s */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        val = !val;
        ret = gpiod_line_set_value(line, val);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE_OFFSET, val);
        fflush(stdout);

        usleep(1000); /* 1 ms = 1000 us */
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <signal.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("i2c write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("i2c write reg failed");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("i2c read failed");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction failed");
        return 1;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/i2c-1");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to acquire I2C bus access");
        close(fd);
        return 1;
    }

    if (i2c_write_byte(fd, ADXL345_POWER_CTL, 0x08) < 0) {
        close(fd);
        return 1;
    }

    while (running) {
        uint8_t data[6];
        if (i2c_read_burst(fd, ADXL345_DATAX0, data, 6) < 0) {
            close(fd);
            return 1;
        }

        int16_t x = (int16_t)((data[1] << 8) | data[0]);
        int16_t y = (int16_t)((data[3] << 8) | data[2]);
        int16_t z = (int16_t)((data[5] << 8) | data[4]);

        printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        fflush(stdout);
        usleep(100000);
    }

    i2c_write_byte(fd, ADXL345_POWER_CTL, 0x00);
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
