#define BCM_PIN_1 4
#define BCM_PIN_2 17
#define BCM_PIN_3 27
#define CONSUMER "gpio-toggle"

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, BCM_PIN_1);
    line2 = gpiod_chip_get_line(chip, BCM_PIN_2);
    line3 = gpiod_chip_get_line(chip, BCM_PIN_3);
    if (!line1 || !line2 || !line3) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request each line as output, initial value LOW */
    ret = gpiod_line_request_output(line1, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output line1");
        goto cleanup;
    }
    ret = gpiod_line_request_output(line2, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output line2");
        goto cleanup;
    }
    ret = gpiod_line_request_output(line3, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output line3");
        goto cleanup;
    }

    printf("GPIO toggling started. Press Ctrl+C to exit.\n");

    while (running) {
        int v1 = gpiod_line_get_value(line1);
        int v2 = gpiod_line_get_value(line2);
        int v3 = gpiod_line_get_value(line3);

