    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip)  gpiod_chip_close(chip);

    printf("GPIO toggling stopped.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, sig_handler) == SIG_ERR) {
        fprintf(stderr, "signal(SIGINT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGTERM, sig_handler) == SIG_ERR) {
        fprintf(stderr, "signal(SIGTERM) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "gpioSetPWMfrequency(%d) failed\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "gpioSetPWMrange(%d) failed\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty = 0;
    while (running) {
        if (gpioPWM(PWM_PIN, duty) != 0) {
            fprintf(stderr, "gpioPWM(%d, %d) failed\n", PWM_PIN, duty);
            break;
        }
        printf("PWM duty cycle set to %d/%d\n", duty, PWM_RANGE);
        fflush(stdout);

        duty = (duty + 1) % (PWM_RANGE + 1);
        time_sleep(0.1);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_4  4
#define GPIO_17 17
#define CONSUMER "gpio-digital-output"

static volatile sig_atomic_t keep_running = 1;

static void handle_sig(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line4 = NULL, *line17 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_sig;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3/4, gpiochip4 on Pi Zero/5) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip4");
    }
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line4 = gpiod_chip_get_line(chip, GPIO_4);
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line4 || !line17) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    ret = gpiod_line_request_output(line4, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO 4)");
        goto cleanup;
    }
    ret = gpiod_line_request_output(line17, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO 17)");
        goto cleanup;
    }

    /* Apply 5 cycles of alternating states */
    for (int i = 0; i < 5 && keep_running; i++) {
        int val = (i % 2 == 0) ? 1 : 0;
        printf("Cycle %d: setting GPIO 4 to %d, GPIO 17 to %d\n", i + 1, val, val);
        fflush(stdout);

        ret = gpiod_line_set_value(line4, val);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 4)");
            goto cleanup;
        }
        ret = gpiod_line_set_value(line17, val);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 17)");
            goto cleanup;
        }

        sleep(1);
    }

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line4) gpiod_line_release(line4);
    if (line17) gpiod_line_release(line17);
    if (chip) gpiod_chip_close(chip);

    return (line4 && line17 && chip) ? EXIT_SUCCESS : EXIT_FAILURE;
}

