#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 22
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define STEP_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_1);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_2);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN_1);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN_2);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN_1);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN_2);
        cleanup();
        return EXIT_FAILURE;
    }

    int duty = 0;
    int direction = 1;

    while (running) {
        if (gpioPWM(PWM_PIN_1, duty) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN_1);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioPWM(PWM_PIN_2, duty) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN_2);
            cleanup();
            return EXIT_FAILURE;
        }

        printf("PWM on GPIO %d: %d, GPIO %d: %d\n", PWM_PIN_1, duty, PWM_PIN_2, duty);
        fflush(stdout);

        duty += direction;
        if (duty >= PWM_RANGE) {
            duty = PWM_RANGE;
            direction = -1;
        } else if (duty <= 0) {
            duty = 0;
            direction = 1;
        }

        usleep(STEP_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

