#include <gpiod.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 23

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Apply HIGH state */
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value (HIGH)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Report state */
    printf("GPIO %d set HIGH\n", GPIO_LINE);
    fflush(stdout);

    /* Wait for signal or 1 second */
    while (keep_running) {
        sleep(1);
    }

    /* Clean shutdown: set LOW and release */
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("GPIO %d set LOW and released\n", GPIO_LINE);
    fflush(stdout);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_OUT_17 17
#define GPIO_OUT_27 27
#define CONSUMER "gpio-toggle"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line27 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the lines */
    line17 = gpiod_chip_get_line(chip, GPIO_OUT_17);
    if (!line17) {
        perror("gpiod_chip_get_line(17)");
        goto cleanup;
    }

    line27 = gpiod_chip_get_line(chip, GPIO_OUT_27);
    if (!line27) {
        perror("gpiod_chip_get_line(27)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value 0 */
    if (gpiod_line_request_output(line17, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(17)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line27, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(27)");
        goto cleanup;
    }

    /* Main loop: toggle each line once every 0.2 seconds */
    while (keep_running) {
        int val17 = gpiod_line_get_value(line17);
        int val27 = gpiod_line_get_value(line27);

        if (val17 < 0) {
            perror("gpiod_line_get_value(17)");
            goto cleanup;
        }
        if (val27 < 0) {
            perror("gpiod_line_get_value(27)");
            goto cleanup;
        }

        printf("GPIO 17: %d, GPIO 27: %d\n", val17, val27);
        fflush(stdout);

        /* Toggle both lines */
        if (gpiod_line_set_value(line17, val17 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value(17)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line27, val27 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value(27)");
            goto cleanup;
        }

        usleep(200000); /* 0.2 seconds */
    }

    ret = EXIT_SUCCESS;

cleanup:
