#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LED_PIN 27

#define SPEED_OF_SOUND 34300.0
#define TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {
        .tv_sec = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL, *echo = NULL, *led = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!trigger || !echo || !led) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hc-sr04-trigger", 0) < 0) {
        perror("gpiod_line_request_output (trigger)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "hc-sr04-led", 0) < 0) {
        perror("gpiod_line_request_output (led)");
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpiod_line_set_value(trigger, 1) < 0) {
            perror("gpiod_line_set_value (trigger high)");
            break;
        }
        sleep_us(10);
        if (gpiod_line_set_value(trigger, 0) < 0) {
            perror("gpiod_line_set_value (trigger low)");
            break;
        }

        long long start_wait = now_us();
        while (gpiod_line_get_value(echo) == 0) {
            if (!running) break;
            if (now_us() - start_wait > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo start\n");
                break;
            }
        }
        if (!running) break;

        long long echo_start = now_us();
        while (gpiod_line_get_value(echo) == 1) {
            if (!running) break;
            if (now_us() - echo_start > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo end\n");
                break;
            }
        }
        if (!running) break;

        long long echo_end = now_us();
        long long pulse_duration = echo_end - echo_start;
        double distance = (pulse_duration * SPEED_OF_SOUND) / 2000000.0;

        printf("Distance: %.2f cm\n", distance);

        if (distance < 2.0) {
            if (gpiod_line_set_value(led, 1) < 0) {
                perror("gpiod_line_set_value (led on)");
                break;
            }
        } else {
            if (gpiod_line_set_value(led, 0) < 0) {
                perror("gpiod_line_set_value (led off)");
                break;
            }
        }

        sleep_us(500000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (led) gpiod_line_release(led);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 18
#define PWM_PIN_2 21
#define PWM_PIN_3 22
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set up signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty_cycle = 0;
    while (running) {
        if (gpioPWM(PWM_PIN_1, duty_cycle) != 0 ||
            gpioPWM(PWM_PIN_2, duty_cycle) != 0 ||
            gpioPWM(PWM_PIN_3, duty_cycle) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            break;
        }

        printf("PWM on GPIO %d, %d, %d set to %d\n", PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, duty_cycle);
        fflush(stdout);

        duty_cycle = (duty_cycle + 1) % (PWM_RANGE + 1);
        time_sleep(0.1);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

