#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define ECHO_PIN_2 18

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static void sleep_us(long long us) {
    struct timespec ts = { .tv_sec = us / 1000000LL, .tv_nsec = (us % 1000000LL) * 1000LL };
    nanosleep(&ts, NULL);
}

static int trigger_pulse(struct gpiod_line *trig) {
    if (gpiod_line_set_value(trig, 1) < 0) return -1;
    sleep_us(10);
    if (gpiod_line_set_value(trig, 0) < 0) return -1;
    return 0;
}

static long long measure_echo(struct gpiod_line *echo, long long timeout_us) {
    long long t0 = now_us();
    while (gpiod_line_get_value(echo) == 0) {
        if (now_us() - t0 > timeout_us) return -1;
    }
    long long t1 = now_us();
    while (gpiod_line_get_value(echo) == 1) {
        if (now_us() - t1 > timeout_us) return -1;
    }
    return now_us() - t1;
}

int main(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    struct gpiod_line *echo1 = gpiod_chip_get_line(chip, ECHO_PIN);
    struct gpiod_line *echo2 = gpiod_chip_get_line(chip, ECHO_PIN_2);
    if (!trig || !echo1 || !echo2) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trig, "hc-sr04", 0) < 0) {
        perror("request_output(trig)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(echo1, "hc-sr04") < 0) {
        perror("request_input(echo1)");
        gpiod_line_release(trig);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(echo2, "hc-sr04") < 0) {
        perror("request_input(echo2)");
        gpiod_line_release(trig);
        gpiod_line_release(echo1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct sigaction sa = { .sa_handler = sig_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        if (trigger_pulse(trig) < 0) {
            fprintf(stderr, "trigger pulse failed\n");
            break;
        }

        long long d1 = measure_echo(echo1, 3000000LL);
        long long d2 = measure_echo(echo2, 3000000LL);

        if (d1 < 0 || d2 < 0) {
            fprintf(stderr, "echo timeout (sensor absent or not responding)\n");
        } else {
            long long d = (d1 + d2) / 2;
            double cm = d * 0.0343 / 2.0;
            printf("Distance: %.2f cm\n", cm);
        }

        sleep_us(100000);
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo1);
    gpiod_line_release(echo2);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

