            fprintf(stderr, "gpiod_line_set_value failed for pin %u\n", pins[i]);
            goto cleanup;
        }
        printf("GPIO %u set LOW\n", pins[i]);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) gpiod_line_release(lines[i]);
    }
    if (chip) gpiod_chip_close(chip);
    return ret;
