#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define PWM_DUTY_CYCLE 128
#define LOOP_DELAY_US 5000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN_1);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN_2);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN_3);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN_1);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN_2);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN_3);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN_1);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN_2);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN_3);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void apply_pwm(int pin, int duty_cycle) {
    if (gpioPWM(pin, duty_cycle) != 0) {
        fprintf(stderr, "Error: failed to set PWM duty cycle on GPIO %d.\n", pin);
    }
}

static void cleanup(void) {
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("PWM control started on GPIO %d, %d, %d. Press Ctrl+C to exit.\n",
           PWM_PIN_1, PWM_PIN_2, PWM_PIN_3);
    fflush(stdout);

    while (running) {
        apply_pwm(PWM_PIN_1, PWM_DUTY_CYCLE);
        apply_pwm(PWM_PIN_2, PWM_DUTY_CYCLE);
        apply_pwm(PWM_PIN_3, PWM_DUTY_CYCLE);
        printf("PWM applied to GPIO %d, %d, %d (duty cycle %d/%d)\n",
               PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_DUTY_CYCLE, PWM_RANGE);
        fflush(stdout);
        usleep(LOOP_DELAY_US);
    }

    cleanup();
    printf("\nPWM control stopped.\n");
    return EXIT_SUCCESS;
}

