#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_6  6
#define GPIO_23 23

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line6 = NULL, *line23 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line6 = gpiod_chip_get_line(chip, GPIO_6);
    if (!line6) {
        perror("gpiod_chip_get_line(6)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line23 = gpiod_chip_get_line(chip, GPIO_23);
    if (!line23) {
        perror("gpiod_chip_get_line(23)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initial value 1 (HIGH) */
    ret = gpiod_line_request_output(line6, "gpio-control", 1);
    if (ret < 0) {
        perror("gpiod_line_request_output(6)");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line23, "gpio-control", 1);
    if (ret < 0) {
        perror("gpiod_line_request_output(23)");
        goto cleanup;
    }

    /* Apply HIGH to both lines */
    ret = gpiod_line_set_value(line6, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value(6)");
        goto cleanup;
    }

    ret = gpiod_line_set_value(line23, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value(23)");
        goto cleanup;
    }

    printf("GPIO 6 and GPIO 23 set to HIGH\n");
    fflush(stdout);

    /* Wait for signal or 5 seconds (whichever comes first) */
    for (int i = 0; i < 50 && running; i++) {
        usleep(100000); /* 100 ms */
    }

    /* Release lines and close chip */
    gpiod_line_release(line6);
    gpiod_line_release(line23);
    gpiod_chip_close(chip);

    printf("GPIO 6 and GPIO 23 set to LOW\n");
    fflush(stdout);
    return EXIT_SUCCESS;

cleanup:
    if (line6) gpiod_line_release(line6);
    if (line23) gpiod_line_release(line23);
    if (chip) gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

